	HERO_DRAGON_ARB_DESCRIPTION = "The nature dragon and protector of the Arboreans, she weaves forests with her breath and makes the wind dance with her wings. Like nature itself, she can be both caring and punishing. Make sure not to litter!",
	HERO_DRAGON_ARB_NAME = "Sylvara",
	HERO_DRAGON_ARB_SPECIAL = "Call of the Forest, Deep Roots, Thorny Breath, Lifebringer, Inner Nature",
	HERO_DRAGON_BONE_DESCRIPTION = "Vez'nan rescued Bonehart on his campaigns; to repay the debt, Bonehart willingly gave his strength and flew across the continent hunting mages who might threaten the dark wizard's plans.",
	HERO_DRAGON_BONE_NAME = "Bonehart",
	HERO_DRAGON_BONE_SPECIAL = "Pestilence, Spine Rain, Plague Cloud, Spreading Burst, Disease Nova, Raise Drakes",
	HERO_DRAGON_DESCRIPTION = "Ashbite is a devoted barbecue enthusiast. Plain or cumin?",
	HERO_DRAGON_GEM_DESCRIPTION = "The cult's activities in the Forgotten Valley interrupted Cosmil's secluded life. To drive out the invaders, this crystal dragon struck a deal with Vez'nan and joined the alliance against a common enemy.",
	HERO_DRAGON_GEM_NAME = "Kosmyr",
	HERO_DRAGON_GEM_SPECIAL = "Paralyzing Breath, Prismatic Shards, Garnet Tomb, Power Conduit, Crystal Avalanche, Untapped Charge",
	HERO_DRAGON_NAME = "Ashbite",
	HERO_DRAGON_SPECIAL = "Dragon Breath, Hunting Feast, Thick Smoke, Fire Barrage, Blazing Reign",
	HERO_DRAGON_SUN_DESCRIPTION = "A majestic being of ancient bloodline, covered in golden scales. Orion and his mate, the moon dragon Lunalis, guard the Cloud Realm together. In battle he gathers the power of the sun, pouring searing flame and dazzling light onto the field.",
	HERO_DRAGON_SUN_NAME = "Orion",
	HERO_DRAGON_SUN_SPECIAL = "Blazing Judgement, Solar Purification, Sun Overload, Sun Gem, Sunfire Storm",
	HERO_DURAX_DESCRIPTION = "A mighty creature born of the Crystal Lake; its spikes and chilling crystal make it the strongest of guardians.",
	HERO_DURAX_NAME = "Durax",
	HERO_DURAX_SPECIAL = "Crystal Lance, Refraction, Deadly Crystal Blade, Crystal Clone, Blue Crystal Fang",
	HERO_DWARF_DESCRIPTION = "Rurin Longbeard is an outstanding warrior of the dwarven clans, wielding the power of the earth. His 'great' hammer smashes every enemy to pieces!",
	HERO_DWARF_NAME = "Rurin Longbeard",
	HERO_DWARF_SPECIAL = "Dwarven Retinue, Great Hammer, Power of the Earth",
	HERO_EISKALT_DESCRIPTION = "Reborn in agony, roaring in the freezing wind - this time, no oath shall be left unfinished!",
	HERO_EISKALT_NAME = "Eiskalt",
	HERO_EISKALT_SPECIAL = "Frozen Breath, Violent Breath, Eternal Permafrost, Avalanche, Ice Peak, Glacier Storm",
	HERO_ELORA_DESCRIPTION = "If magic was made of ice, it would melt, run through her veins, and freeze again. Good, but merciless, she will freeze and shatter any who cross her!",
	HERO_ELORA_NAME = "Elora Wintersong",
	HERO_ELORA_SPECIAL = "Eternal Permafrost, Ice Storm, Frost Breath",
	HERO_ELVES_ARCHER_DESCRIPTION = "Once a mage apprentice of outstanding magical talent, he took the ranger's path out of admiration for the elven princess. Eridan is the youngest and most promising ranger general of the elven kingdom.",
	HERO_ELVES_ARCHER_NAME = "Eridan",
	HERO_ELVES_ARCHER_SPECIAL = "Multishot, Flash Step, Double Blades, Porcupine, Arrow Rain, Bodyguard",
	HERO_ELVES_BARD_NAME = "BARD",
	HERO_ELVES_DENAS_DESCRIPTION = "As a prince, Denas longed to win glory: approachable, dashing and fearless, fond of throwing coins around and eating big chicken legs.",
	HERO_ELVES_DENAS_NAME = "Prince Denas",
	HERO_ELVES_DENAS_SPECIAL = "Ricochet Shield, Dashing Pose, Mighty Hammer Blow, Royal Guard, Pocket Money, Big Chicken Leg",
	HERO_ELVES_GRIPHON_RIDER_NAME = "GRIPHON",
	HERO_FAUSTUS_DESCRIPTION = "The guardian dragon of the elves, his life bound tightly to the Tear of Elynie. That relic must never fall into enemy hands!",
	HERO_FAUSTUS_NAME = "Faustus",
	HERO_FAUSTUS_SPECIAL = "Teleport Rune, Dragon Rage, Dragon Lance, Liquid Smoke, Enervation, Tendrils",
	HERO_GERALD_DESCRIPTION = "Defender of the righteous, punisher of the dark, protector of the innocent, crusher of evil beings, Gerald Lightseeker is the uncanny of Linirea's armed forces!",
	HERO_GERALD_NAME = "Sir Gerald",
	HERO_GERALD_SPECIAL = "Holy Support, Courage, Shield of Retribution, Holy Strike",
	HERO_GIANT_DESCRIPTION = "When the saurians' picks struck this rock giant, the earth shook and Graul joined our ranks in a fury. Perhaps we should be glad it was not our dwarven friends who dug him up first...",
	HERO_GIANT_NAME = "Grawl",
	HERO_GIANT_SPECIAL = "Boulder Throw, Crystal Elbow, Earthshake, Fortress Stance",
	HERO_HACKSAW_DESCRIPTION = "For a Gnomish inventor, giant oak trees or colossal foes make no difference. Riding his Mechanical Marvel / Contraption, he can shred anything in his path. Gangway... Gnome behind the wheel!",
	HERO_HACKSAW_NAME = "Hacksaw",
	HERO_HACKSAW_SPECIAL = "Flying Sawblade, Tiiiimber!",
	HERO_HALLOWEEN_VAMPIRESS_NAME = "Lucrezia",
	HERO_HUNTER_DESCRIPTION = "Half demon hunter, half vampire; descendant of both humans and the blood kin. Her hunting rifle never misses, and her claws never fail.",
	HERO_HUNTER_NAME = "Anya",
	HERO_HUNTER_SPECIAL = "Argent Storm, Vampiric Claw, Dusk Beasts, Misty Step, Father's Spirit",
	HERO_IGNUS_DESCRIPTION = "Burn the kingdom's enemies with the blaze of a thousand stars! Forge victory in his raging flames, and consume evil in fire and brimstone!",
	HERO_IGNUS_NAME = "Ignus",
	HERO_IGNUS_SPECIAL = "Surge of Flame, Flaming Frenzy",
	HERO_INGVAR_DESCRIPTION = "A fierce warrior from the northern wastes. His physical and spiritual prowess are unparalleled, for he commands the might of a bear and invokes the aid of his ancestors!",
	HERO_INGVAR_NAME = "Ingvar Bearclaw",
	HERO_INGVAR_SPECIAL = "Ancestor Call, Bear form",
	HERO_ISFET_DESCRIPTION = "Long ago Isfet, a warlock of forgotten legend, used dark magic to unlock the secrets of genie magic. While he slumbered in an ancient pyramid, Vez'nan's evil aura brought him back as an undying mystic power, ready to shape the desert's fate once more.",
	HERO_ISFET_NAME = "Isfet",
	HERO_ISFET_SPECIAL = "Black Locusts, Toad's Curse, Icefire Rain, Blood Torment, Dark Storm",
	HERO_JIGOU_DESCRIPTION = "This ferocious, terrifying beast was imprisoned in the northern ice mountains, and woke from its slumber only to serve Vez'nan. At its master's command it mercilessly crushes every enemy.",
	HERO_JIGOU_NAME = "Jigou",
	HERO_JIGOU_SPECIAL = "Snowball, Frost Breath, Ground Smash, Glacier Form, Ice Field, Yeti Blood",
	HERO_LAVA_DESCRIPTION = "Lava is a frenzied warrior from the volcanic lands: the closer to death she comes, the stronger she grows, and she can destroy anything in her way with volcanic eruptions.",
	HERO_LAVA_NAME = "Kratoa",
	HERO_LAVA_SPECIAL = "Temper Tantrum, Heart of Flame, Double Trouble, Wild Eruption, Blazing Sweep",
	HERO_LILITH_DESCRIPTION = "Lilith is the child of a balrog and an angel, and so wields the power of both hell and heaven. Now she is determined to use those powers to protect her friends.",
	HERO_LILITH_NAME = "Lilith",
	HERO_LILITH_SPECIAL = "Infernal Wheel, Reap, Heavenly Chaos, Soul Eater, Resurrection, Descent",
	HERO_LUMENIR_DESCRIPTION = "Soaring between the realms, Lumenir stands as the avatar of justice and resolve. She is the fabled Lightbringer, revered by the Linirean paladins, to whom she bestows her blessings, granting them great powers to aid in their fight against evil.",
	HERO_LUMENIR_NAME = "Lumenir",
	HERO_LUMENIR_SPECIAL = "Radiant Wave, Light Companion, Blessing of Retribution, Celestial Judgement, Call of Triumph",
	HERO_LYNN_DESCRIPTION = "Once a valued officer under General Baj'Nimen, she turned against her own kin upon learning of his evil plans. Though cursed by fate, Lynn - unlike the weak - never flinched, and marches bravely on along her own path.",
	HERO_LYNN_NAME = "Lynn",
	HERO_LYNN_SPECIAL = "Hexfury, Curse of Despair, Weakening Curse, Sigil of Misfortune, Fate Sealed",
	HERO_MAGNUS_DESCRIPTION = "Unleash the arcane forces of Linirea, let loose a mystical storm, and spellbind your enemies with his arcane arts and thirst for knowledge!",
	HERO_MAGNUS_NAME = "Magnus Spellbane",
	HERO_MAGNUS_SPECIAL = "Mirage, Arcane Storm",
	HERO_MALIK_DESCRIPTION = "From a land far, far away, comes a Hero with unmatched strength, untamed mind, and unbroken will. A destructive force, an unleashed fury, a bullet train attitude!",
	HERO_MALIK_NAME = "Malik Hammerfury",
	HERO_MALIK_SPECIAL = "Shock and Awe, Hammer Smash, Earthquake",
	HERO_MARGOSA_DESCRIPTION = "The wounds she suffered when Lord Vasile fell were long ago carved deep into Lady Margosa's memory. She recovered her strength in a cave cut off from the world, and her power and her hatred of Linirea grew with each passing day. Now she returns to satisfy her thirst for blood.",
	HERO_MARGOSA_NAME = "Lady Margosa",
	HERO_MARGOSA_SPECIAL = "Bat Drain, Fog of Despair, Dark Call, Vampire's Touch, Beast Form, Bloodthirst",
	HERO_MECHA_DESCRIPTION = "Born from the mind of two mad goblin tinkerers and built on the foundations of stolen dwarven technology, Onagro is the definitive greenskin war machine and a frightening sight for the enemies of the Dark Army.",
	HERO_MECHA_NAME = "Onagro",
	HERO_MECHA_SPECIAL = "Goblidrones, Tar Bomb, War Machine, Self-Destruct, Ultimate Bombardment",
	HERO_MINOTAUR_DESCRIPTION = "Savage charges to fear, teleporting sorcery to confound, a razor-sharp axe that nothing can withstand - Kaz is a true battle maniac!",
	HERO_MINOTAUR_NAME = "Kahz",
	HERO_MINOTAUR_SPECIAL = "Bull Rush, Daring Strike, Daedalus' Maze, Bison Roar, Axe Storm",
	HERO_MIRAGE_DESCRIPTION = "A master assassin, elegant and deadly. By the time the enemy sees her shadow, her blades have already torn it apart.",
	HERO_MIRAGE_NAME = "Mirage",
	HERO_MIRAGE_SPECIAL = "Shadow Swap, Shadow Dance, Backstab",
	HERO_MONKEY_GOD_DESCRIPTION = "An ancient deity and master of the staff; his divine wrath greatly weakens the enemy's will to fight.",
	HERO_MONKEY_GOD_NAME = "Saitam",
	HERO_MONKEY_GOD_SPECIAL = "Tetsubo Storm, Spinning Pole, Monkey Palm, Divine Wrath, Divine Nature",
	HERO_MONK_DESCRIPTION = "A monk of mysterious Eastern power, perfect in body and spirit, and senior brother to Black Tiger Afu.",
	HERO_MONK_NAME = "Kutsao",
	HERO_MONK_SPECIAL = "Tiger Style, Snake Style, Leopard Style, Dragon Style, Crane Style, Weapon Mastery",
	HERO_MORTEMIS_DESCRIPTION = "Unwilling to die, the old wizard king traded his humanity for the secret arts of witchcraft. Now he joins Vez'nan's army as one of the undead, chasing the dark power he was promised.",
	HERO_MORTEMIS_GOLEM_NAME = "Zombie Golem",
	HERO_MORTEMIS_NAME = "Mortemis",
	HERO_MORTEMIS_SPECIAL = "Night Shriek, Land of Decay, Hopeless Ones, Servants of the Undead, Decayed Guard, Dark Army",
	HERO_MORTEMIS_ZOMBIE_NAME = "Zombie",
	HERO_MUYRN_DESCRIPTION = "Despite his childish looks, the trickster Nyru has been protecting the forest for hundreds of years using his connection with the forces of nature. He joined the Alliance in order to put an end to the increasing waves of invaders threatening his home.",
	HERO_MUYRN_NAME = "Nyru",
	HERO_MUYRN_SPECIAL = "Leaf Whirlwind, Enfeeblement Charm, Sentinel Wisps, Verdant Blast, Root Defender",
	HERO_OLOCH_DESCRIPTION = "The demon Oloch trained in the dark arts and once helped Vez'nan escape prison in exchange for a share of his power. Now he fights alongside Vez'nan while waiting for the moment to carry out his own sinister plan and turn the bargain in his favor.",
	HERO_OLOCH_ILLUSION_NAME = "Oloch's Phantom",
	HERO_OLOCH_NAME = "Oloch",
	HERO_OLOCH_SPECIAL = "Infernal Combustion, Self-Replication, Magma Eruption, Hell Infusion, Demon Blast, Sigil of Isolation",
	HERO_ONI_DESCRIPTION = "A relentless warrior, in search of vengeance. His name inspires fear among the demon armies he faces, armed with his dark honor and his blazing katanas.",
	HERO_ONI_NAME = "Oni",
	HERO_ONI_SPECIAL = "Death Strike, Sword Torment",
	HERO_ORC_DESCRIPTION = "Veruk is a respected warrior of the orc tribes, who once fled the gladiator pits and his slavery to support one of the Warmonger leaders. Now free, he devotes himself to aiding his fellow greenskins in trouble.",
	HERO_ORC_NAME = "Veruk",
	HERO_ORC_SPECIAL = "Battle Lust, Gladiator Stance, Brute Force, Aimed Slash, Rallying Cry, Warmongers",
	HERO_PHOENIX_DESCRIPTION = "The legendary phoenix, reborn in flame. Its fire purifies all evil.",
	HERO_PHOENIX_NAME = "Phoenix",
	HERO_PHOENIX_SPECIAL = "Purification, Immolate, Ember Field, Blazing Offspring, Ring of Fire",
	HERO_PIRATE_DESCRIPTION = "A treasure-loving pirate captain, leader of the pirates, and an expert at mopping up battlefields. Want some gold?",
	HERO_PIRATE_NAME = "Captain Blackthorne",
	HERO_PIRATE_SPECIAL = "Powder Cluster, Kraken's Touch, Treasure Hunt",
	HERO_PRIEST_DESCRIPTION = "A resolute and radiant priestess of the Holy Light, healing soldiers with holy light, shielding the battle line with wings of light, and forging bulwarks with benedictions. Her brilliance fills the field and kindles hope in every soldier.",
	HERO_PRIEST_NAME = "Dierdre",
	HERO_PRIEST_SPECIAL = "Holy Light, Sacred Benediction, Wings of Light",
	HERO_RAELYN_DESCRIPTION = "The imposing Raelyn was born to lead dark knights into the charge. Her cruelty and defiance earned Vez'nan's approval and struck terror into the people of Linirea. Fond of a good fight, she became the first to willingly join the dark wizard's ranks.",
	HERO_RAELYN_NAME = "Raelyn",
	HERO_RAELYN_SPECIAL = "Command Orders, Cruel Strike, Onslaught, Inspire Fear, Unbreakable",
	HERO_RAELYN_ULTIMATE_ENTITY_NAME = "Dark Knight",
	HERO_RAG_DESCRIPTION = "Rag is a noisy little gnome mage who loves turning things into plush toys. As for how he came by the big Rig underneath him - nobody knows!",
	HERO_RAG_NAME = "Razz & Rags",
	HERO_RAG_SPECIAL = "Boom Bunnies, Knock Knock Knock, Gnome Rage, Plushify, Changeling",
	HERO_REGSON_DESCRIPTION = "Once a prince of the twilight elves, now an avenger who leaves only ruin behind; Reg'son's blade never rests, just like his fury.",
	HERO_REGSON_NAME = "Reg'son",
	HERO_REGSON_SPECIAL = "Blade Dance, Deathwish, Eldritch Blade, Shadow Strike, Death's Kiss",
	HERO_ROBOT_DESCRIPTION = "The Dark Army forgemasters outdid themselves by creating a warring automaton which they aptly named Warhead. Bolstered by fiery engines and unbothered by emotions, Warhead lunges into battle disregarding both friend and foe.",
	HERO_ROBOT_NAME = "Warhead",
	HERO_ROBOT_SPECIAL = "Deep Impact, Smokescreen, War Sacrifice, Power Uppercut, Rail Cannon",
	HERO_ROOM_10YR_BUFFED_2_DESC = "In Iron state, Ten'Shi leaps high every %s seconds, dealing %s to enemies within %s range and shattering the ground into %s shards, each dealing %s to enemies within %s range with a %s chance to stun them for %s seconds.",
	HERO_ROOM_10YR_BUFFED_2_NAME = "Earthshaker",
	HERO_ROOM_10YR_BUFFED_DESC = "Every %s seconds, if at least %s enemies are nearby, Ten'Shi enters Iron state, his movement speed rises to %s and he becomes immune to basic damage types for %s seconds. In Iron state he spins rapidly every %s seconds, performing a %s-hit combo on enemies within %s range, each hit dealing %s. When the rally distance is far he leaves Iron state on his own, refunds the cooldown and teleports to the rally point. This skill does not go on cooldown while in Iron state.",
	HERO_ROOM_10YR_BUFFED_NAME = "Iron Time",
	HERO_ROOM_10YR_RAIN_DESC = "%sTen'Shi calls upon heaven and earth, summoning %s fireballs, each dealing %s to enemies within %s range. On landing they leave scorched earth that deals %s to enemies within %s range every %s seconds for %s seconds. Every second cooldown, Ten'Shi also releases an empowered version of this skill, summoning a fireball twice the size.",
	HERO_ROOM_10YR_RAIN_NAME = "Firerush!",
	HERO_ROOM_ALIEN_ABDUCTION_DESC = "%sXata calls the mothership and randomly abducts up to %s enemies whose total health is under %s, or one enemy with no health limit, removing them from the battlefield.",
	HERO_ROOM_ALIEN_ABDUCTION_NAME = "Mothership Hijack",
	HERO_ROOM_ALIEN_ENERGYGLAIVE_DESC = "%sXata throws an energy dart, dealing %s and slowing by %s%% for %s seconds. Each time the dart hits an enemy it has a %s chance to ricochet to a nearby enemy.",
	HERO_ROOM_ALIEN_ENERGYGLAIVE_NAME = "Energy Dart",
	HERO_ROOM_ALIEN_FINALCOUNTDOWN_DESC = "Xata's revive time is 6 seconds, and levelling up refreshes all skill cooldowns. When his health runs out Xata self-destructs, dealing %s to nearby enemies and stunning them for %s seconds.",
	HERO_ROOM_ALIEN_FINALCOUNTDOWN_NAME = "Last Resort",
	HERO_ROOM_ALIEN_PURIFICATIONPROTOCOL_DESC = "%sXata summons a purification drone that stays for %s seconds, automatically locking onto enemies to keep them stunned and dealing %s every %s seconds.",
	HERO_ROOM_ALIEN_PURIFICATIONPROTOCOL_NAME = "Purge Protocol",
	HERO_ROOM_ALIEN_VIBROBLADES_DESC = "Each of Xata's basic attacks carries an extra %s.",
	HERO_ROOM_ALIEN_VIBROBLADES_NAME = "Humming Blade",
	HERO_ROOM_ALLERIA_CALLOFWILD_DESC = "Every %s seconds, the princess summons a wildcat that fights alongside her and is invulnerable while summoned. The wildcat has %s health and deals %s per attack.",
	HERO_ROOM_ALLERIA_CALLOFWILD_NAME = "Call of the Wild",
	HERO_ROOM_ALLERIA_MISSILESHOT_DESC = "Every %s seconds, the princess fires a hunter's arrow that tracks and pierces up to %s targets, dealing %s to each.",
	HERO_ROOM_ALLERIA_MISSILESHOT_NAME = "Hunter's Arrow",
	HERO_ROOM_ALLERIA_MULTISHOT_DESC = "Every %s seconds, the princess aims at a small group of enemies and distributes her arrows wisely, firing %s elven arrows that deal %s. When extra arrows hit the same enemy they deal %s instead.",
	HERO_ROOM_ALLERIA_MULTISHOT_NAME = "Multishot",
	HERO_ROOM_ALRIC_FLURRY_DESC = "%sThe Sand King launches %s slashes at enemies in front of him, each dealing %s equal to his basic attack. The experience this skill gains depends on the total damage dealt.",
	HERO_ROOM_ALRIC_FLURRY_NAME = "Blood Slash",
	HERO_ROOM_ALRIC_SANDWARRIORS_2_DESC = "Alric's heart is bound tightly to the desert and his people. When rallied from afar, Alric becomes a sand tornado, gaining %s movement speed. When a Sand Warrior's body disperses, its soul drifts to Alric, restoring %s%% of the Sand Warrior's maximum health and reducing Blood Slash's remaining cooldown by 10%%.",
	HERO_ROOM_ALRIC_SANDWARRIORS_2_NAME = "Heart of the Desert",
	HERO_ROOM_ALRIC_SANDWARRIORS_DESC = "%sThe Sand King awakens %s Sand Warriors to fight alongside him. They have %s health, deal %s per attack, stay for %s seconds, and fear no deadly poison, werewolf transformation or zombification.",
	HERO_ROOM_ALRIC_SANDWARRIORS_NAME = "Sand Warriors",
	HERO_ROOM_ALRIC_SPIKEDARMOR_DESC = "The Sand King gains an extra %s points of spike armor.",
	HERO_ROOM_ALRIC_SPIKEDARMOR_NAME = "Thornmail",
	HERO_ROOM_ARIVAN_ICY_PRISON_DESC = "%sArivan fires an ice arrow that deals %s and freezes the enemy for %s seconds.",
	HERO_ROOM_ARIVAN_ICY_PRISON_NAME = "Ice Arrow",
	HERO_ROOM_ARIVAN_LIGHTNING_ROD_DESC = "%sArivan fires a lightning bolt that deals %s to the enemy.",
	HERO_ROOM_ARIVAN_LIGHTNING_ROD_NAME = "Lightning Bolt",
	HERO_ROOM_ARIVAN_SEAL_OF_FIRE_DESC = "%sArivan casts Fireball, firing %s fireballs in a row, each dealing %s to enemies within %s range.",
	HERO_ROOM_ARIVAN_SEAL_OF_FIRE_NAME = "Fireball",
	HERO_ROOM_ARIVAN_STONE_DANCE_DESC = "Elemental mages use the power of stone to protect themselves. %sArivan summons up to %s stone shields, each absorbing %s damage. Each shield Arivan holds increases his melee attack damage by %s. When a shield shatters it releases elemental energy, reducing the cooldown of Lightning Bolt, Fireball and Ice Arrow by 1 second. Each of Arivan's basic attacks has a 20%% chance to create a shield; against bosses the chance drops to 10%%. Arivan can still use skills while blocking.",
	HERO_ROOM_ARIVAN_STONE_DANCE_NAME = "Stone Shield",
	HERO_ROOM_ARIVAN_ULTIMATE_DESC = "%sArivan unleashes the power of the elements and summons a storm that advances for %s seconds. The storm slows enemies within %s range by %s%%, deals %s to enemies within %s range every %s seconds, has a %s chance every %s seconds to freeze enemies within %s range for %s seconds, and has a %s chance every %s seconds to deal %s to enemies within %s range.",
	HERO_ROOM_ARIVAN_ULTIMATE_NAME = "Elemental Fury",
	HERO_ROOM_ASRA_ONIX_ARROWS_DESC = "%sFires %s arrows at the target, each dealing %s.",
	HERO_ROOM_ASRA_ONIX_ARROWS_NAME = "Rock Serpent Arrow",
	HERO_ROOM_ASRA_QUIVER_OF_SORROW_DESC = "Each of Asra's shots reduces the target's armor by %s.",
	HERO_ROOM_ASRA_QUIVER_OF_SORROW_NAME = "Quiver of Sorrow",
	HERO_ROOM_ASRA_SHIELD_OF_SHADOWS_DESC = "%sAfter being attacked, Asra casts a shield that blocks %s damage and lasts %s seconds. When the shield is removed, Asra's damage is increased by %s%% for %s seconds.",
	HERO_ROOM_ASRA_SHIELD_OF_SHADOWS_NAME = "Shadow Shield",
	HERO_ROOM_ASRA_SPIDER_BITE_DESC = "%sStrikes the enemy with a poisoned dagger, dealing %s deadly poison damage every %s seconds until the enemy dies.",
	HERO_ROOM_ASRA_SPIDER_BITE_NAME = "Spider Bite",
	HERO_ROOM_ASRA_ULTIMATE_2_DESC = "%sFires several poison arrows across a wide area, each dealing %s to all enemies in the area and applying deadly poison that deals %s every %s seconds for %s seconds.",
	HERO_ROOM_ASRA_ULTIMATE_2_NAME = "Poison Rain",
	HERO_ROOM_ASRA_ULTIMATE_DESC = "When rallied over a long distance, Asra teleports, removes all status effects and increases her attack speed by 25% for 8 seconds.",
	HERO_ROOM_ASRA_ULTIMATE_NAME = "Shadow Dance",
	HERO_ROOM_BEASTMASTER_BOARMASTER_DESC = "%sThe Beastmaster randomly summons %s boars or wolves to fight alongside him. Boars have %s and deal %s per attack; wolves have %s, deal %s per attack and have a %s chance to dodge attacks.",
	HERO_ROOM_BEASTMASTER_BOARMASTER_NAME = "Boar Friend",
	HERO_ROOM_BEASTMASTER_DEEPLASHES_2_DESC = "The Beastmaster is immune to deadly poison and restores %s health every %s seconds.",
	HERO_ROOM_BEASTMASTER_DEEPLASHES_2_NAME = "Wild Constitution",
	HERO_ROOM_BEASTMASTER_DEEPLASHES_DESC = "%sThe Beastmaster swings his whip, dealing %s to enemies and making them bleed for a total of %s over %s seconds.",
	HERO_ROOM_BEASTMASTER_DEEPLASHES_NAME = "Wrath Lash",
	HERO_ROOM_BEASTMASTER_FALCONER_DESC = "The Beastmaster is accompanied by %s falcons. A falcon attacks every %s seconds, dealing %s and slowing the target by %s%% for %s seconds.",
	HERO_ROOM_BEASTMASTER_FALCONER_NAME = "Falcon Friend",
	HERO_ROOM_BEASTMASTER_STAMPEDE_DESC = "%sThe Beastmaster summons %s rhinos; their charge deals %s to enemies along the path and has a %s chance to stun them for %s seconds. The rhinos stay for %s seconds.",
	HERO_ROOM_BEASTMASTER_STAMPEDE_NAME = "Rhino Friend",
	HERO_ROOM_BERESAD_CONFLAGRATION_DESC = "%sBeresad breathes searing flame, scorching the area ahead and leaving scorched earth for %s seconds that deals %s every %s seconds.",
	HERO_ROOM_BERESAD_CONFLAGRATION_NAME = "Conflagration",
	HERO_ROOM_BERESAD_DRAGON_SPAWN_DESC = "%sFires a puppet that deals %s on landing. The puppet has %s health, deals %s per attack and stays for %s seconds. It cannot regenerate health, but is also unaffected by fire, deadly poison, bleeding, lycanthropy and zombification.",
	HERO_ROOM_BERESAD_DRAGON_SPAWN_NAME = "Dragon Spawn",
	HERO_ROOM_BERESAD_FEAR_DRAGON_DESC = "%sLets out a deafening roar that terrifies up to %s enemies, making them flee and speeding them up by %s%% for %s seconds.",
	HERO_ROOM_BERESAD_FEAR_DRAGON_NAME = "Dread Dragon",
	HERO_ROOM_BERESAD_REMOVE_EXISTENCE_DESC = "%sFires an annihilation ray that executes the target and deals %s to nearby enemies. This skill is only used on enemies with more than 750 health.",
	HERO_ROOM_BERESAD_REMOVE_EXISTENCE_NAME = "Total Annihilation",
	HERO_ROOM_BERESAD_ULTIMATE_2_DESC = "%sSummons a rain of hellfire that deals %s to all enemies every %s seconds for %s seconds.",
	HERO_ROOM_BERESAD_ULTIMATE_2_NAME = "Hellfire",
