	HERO_ROOM_THOR_CHAINLIGHTNING_2_NAME = "Lightning Relay",
	HERO_ROOM_THOR_CHAINLIGHTNING_DESC = "Each of Thor's attacks has a %s chance to trigger %s currents distributed among random enemies, dealing %s and applying a stacking shock effect that deals %s every %s seconds for %s seconds. Triggering Thunder Strike speeds up Mjolnir's cooldown by 1 second. Thor's basic attack speed is raised by %s%%.",
	HERO_ROOM_THOR_CHAINLIGHTNING_NAME = "Thunder Strike",
	HERO_ROOM_THOR_THUNDERCLAP_DESC = "%sThor hurls Mjolnir at a target, dealing %s to it and %s to enemies within %s range, stunning them for %s-%s seconds.",
	HERO_ROOM_THOR_THUNDERCLAP_NAME = "Mjolnir",
	HERO_ROOM_TRAMIN_BOMBOTS_DESC = "%sThrows a self-destruct bot at the enemy; after landing it charges along the path and explodes, dealing %s to enemies within %s range.",
	HERO_ROOM_TRAMIN_BOMBOTS_NAME = "Self-Destruct Bot",
	HERO_ROOM_TRAMIN_FLASHBANG_DESC = "%sThrows a flashbang at the enemy, stunning it for %s seconds and dealing basic attack damage.",
	HERO_ROOM_TRAMIN_FLASHBANG_NAME = "Flashbang",
	HERO_ROOM_TRAMIN_NITRO_RUSH_DESC = "%sTramin drinks a glass of nitroglycerin, speeding up his attack speed by %s%%, halving his basic attack cooldown again, for %s seconds.",
	HERO_ROOM_TRAMIN_NITRO_RUSH_NAME = "Nitro Dash",
	HERO_ROOM_TRAMIN_ROCKET_BARRAGE_DESC = "%sFires %s seeking missiles at enemies, each dealing %s.",
	HERO_ROOM_TRAMIN_ROCKET_BARRAGE_NAME = "Rocket Barrage",
	HERO_ROOM_TRAMIN_ULTIMATE_2_DESC = "%sDrops a box that produces bombs, releasing %s bombs that travel along the path; each explosion deals %s to enemies.",
	HERO_ROOM_TRAMIN_ULTIMATE_2_NAME = "Mad Bomber",
	HERO_ROOM_TRAMIN_ULTIMATE_DESC = "When rallied over a long distance Tramin dispels special effects and rocket-jumps to reposition quickly.",
	HERO_ROOM_TRAMIN_ULTIMATE_NAME = "Rocket Jump",
	HERO_ROOM_VAMPIRESS_SLAYER_2_DESC = "Lucrezia grows through slaughter: each enemy she kills restores %s health and increases her %s maximum health, %s basic attack damage, %s physical resistance, %s magic resistance, %s movement speed and %s Crimson Dance damage radius, and permanently reduces the cooldown of Life Drain and Crimson Dance by %s seconds. These bonuses stack up to %s times.",
	HERO_ROOM_VAMPIRESS_SLAYER_2_NAME = "Slaughter Growth",
	HERO_ROOM_VAMPIRESS_SLAYER_3_DESC = "Lucrezia is immune to poison, restores 3 health with each basic attack, and counts as an undead unit. When moving over a long distance she turns into a bat and flies, gaining %s movement speed.",
	HERO_ROOM_VAMPIRESS_SLAYER_3_NAME = "Blood Offspring",
	HERO_ROOM_VAMPIRESS_SLAYER_DESC = "%sLucrezia deals %s to enemies within %s range. This damage is x%s against vampire ladies.",
	HERO_ROOM_VAMPIRESS_SLAYER_NAME = "Crimson Dance",
	HERO_ROOM_VAMPIRESS_VAMPIRISM_DESC = "%sLucrezia drains the enemy's life, dealing %s and restoring the same amount as health. The drained enemy bleeds for %s seconds, taking %s every %s seconds.",
	HERO_ROOM_VAMPIRESS_VAMPIRISM_NAME = "Life Drain",
	HERO_ROOM_VAN_HELSING_BEACONOFLIGHT_DESC = "Dante's beacon of light inspires allies, multiplying the damage of nearby friendly units by %s. After Dante dies his spirit remains on the battlefield.",
	HERO_ROOM_VAN_HELSING_BEACONOFLIGHT_NAME = "Beacon of Light",
	HERO_ROOM_VAN_HELSING_HOLYGRENADE_DESC = "%sDante throws a holy water bomb at a silenceable unit, silencing enemies within %s range for %s seconds.",
	HERO_ROOM_VAN_HELSING_HOLYGRENADE_NAME = "Holy Water Bomb",
	HERO_ROOM_VAN_HELSING_MULTISHOOT_DESC = "%sDante fires %s shots in a row with his pistols, each dealing %s. When the target dies he switches to the nearest enemy.",
	HERO_ROOM_VAN_HELSING_MULTISHOOT_NAME = "Deadly Rapid Fire",
	HERO_ROOM_VAN_HELSING_RELICOFPOWER_DESC = "%sDante uses the relic's power on the enemy in front of him, reducing its armor and magic resistance by %s%%. This skill is only used on enemies with more than 500 health and armor/magic resistance above 0.",
	HERO_ROOM_VAN_HELSING_RELICOFPOWER_NAME = "Power of the Ruins",
	HERO_ROOM_VAN_HELSING_SILVERBULLET_DESC = "%sDante fires a pure silver bullet, dealing %s. This attack prioritizes enemies very close to the hold point, then the enemy with the highest effective health after armor. Against werewolves that effective health is doubled, and so is the damage.",
	HERO_ROOM_VAN_HELSING_SILVERBULLET_NAME = "Silver Bullets",
	HERO_ROOM_VENOM_BERSERKER_2_DESC = "%sTriggers automatically when Grimson's health falls below %s%%, fully transforming him for %s seconds. While transformed his attack damage is raised by %s%% and each attack restores %s%% of his total health. In this state Renew Flesh's trigger threshold is raised by 50%%, and triggering Renew Flesh ends the wild transformation and refunds 50%% of its cooldown. Health restored during the transformation can pull Grimson back from death.",
	HERO_ROOM_VENOM_BERSERKER_2_NAME = "Inner Beast",
	HERO_ROOM_VENOM_BERSERKER_3_DESC = "%sGrimson scatters %s spikes along the path, each dealing %s to enemies within %s range.",
	HERO_ROOM_VENOM_BERSERKER_3_NAME = "Deadly Spikes",
	HERO_ROOM_VENOM_BERSERKER_4_DESC = "Grimson can devour a group of enemies below %s%% health and deals %s to the rest. Each enemy devoured restores %s%% of Grimson's total health. The greater the total health percentage devoured, the longer the cooldown, up to %s seconds.",
	HERO_ROOM_VENOM_BERSERKER_4_NAME = "Renew Flesh",
	HERO_ROOM_VENOM_BERSERKER_5_DESC = "%sGrimson spreads a sticky substance within %s range, setting enemy movement speed to x%s%% for %s seconds, then dealing %s to them.",
	HERO_ROOM_VENOM_BERSERKER_5_NAME = "Creeping Death",
	HERO_ROOM_VENOM_BERSERKER_DESC = "%sGrimson attacks an enemy at range, dealing %s and applying a bleed that deals %s every %s seconds for %s seconds.",
	HERO_ROOM_VENOM_BERSERKER_NAME = "Heartseeker",
	HERO_ROOM_VESPER_BERSERKER_2_DESC = "%sVesper fires a ricochet arrow that deals %s and bounces to nearby enemies after hitting, up to %s bounces. Enemies hit have their movement speed set to x%s%% for %s seconds.",
	HERO_ROOM_VESPER_BERSERKER_2_NAME = "Ricochet",
	HERO_ROOM_VESPER_BERSERKER_3_DESC = "%sWhen attacked, Vesper refreshes the cooldowns of Arrow to the Knee and Ricochet, dodges backwards and fires %s arrows, each dealing %s.",
	HERO_ROOM_VESPER_BERSERKER_3_NAME = "Disengage",
	HERO_ROOM_VESPER_BERSERKER_4_DESC = "%sVesper's martial skill blooms as she attacks the enemy %s times in a row, each dealing %s.",
	HERO_ROOM_VESPER_BERSERKER_4_NAME = "Martial Flourish",
	HERO_ROOM_VESPER_BERSERKER_5_DESC = "%sVesper summons an arrow storm, firing %s arrows within %s range, each dealing %s to enemies within %s range and setting their movement speed to x%s%% for %s seconds.",
	HERO_ROOM_VESPER_BERSERKER_5_NAME = "Arrow Storm",
	HERO_ROOM_VESPER_BERSERKER_DESC = "%sVesper fires an arrow to the knee that pierces enemies over %s distance, dealing %s and stunning them for %s seconds.",
	HERO_ROOM_VESPER_BERSERKER_NAME = "Arrow to the Knee",
	HERO_ROOM_VEZNAN_ARCANENOVA_DESC = "%sVez'nan detonates arcane energy, dealing %s within %s range and setting enemy movement speed to x%s%% for %s seconds.",
	HERO_ROOM_VEZNAN_ARCANENOVA_NAME = "Arcane Nova",
	HERO_ROOM_VEZNAN_SHACKLES_DESC = "%sVez'nan shackles up to %s enemies for %s seconds, dealing %s every %s seconds.",
	HERO_ROOM_VEZNAN_SHACKLES_NAME = "Cage of Pain",
	HERO_ROOM_VEZNAN_SOULBURN_DESC = "%sVez'nan transmutes several enemies whose total health is under %s, or without limit the enemy with the highest health in sight.",
	HERO_ROOM_VEZNAN_SOULBURN_NAME = "Soul Split",
	HERO_ROOM_VEZNAN_ULTIMATE_DESC = "%sVez'nan summons a greater demon that stuns enemies within %s range for %s seconds. The demon can be rallied, stays %s seconds, has %s and deals %s per attack.",
	HERO_ROOM_VEZNAN_ULTIMATE_NAME = "Demon Pact",
	HERO_ROOM_VOODOO_WITCH_BONEDANCE_DESC = "Whenever an enemy or ally dies near the witch she draws on the power of the dead, summoning Laughing Skulls that fight alongside her. At most %s Laughing Skulls can exist.",
	HERO_ROOM_VOODOO_WITCH_BONEDANCE_NAME = "Skeleton Dance",
	HERO_ROOM_VOODOO_WITCH_DEATHAURA_DESC = "The witch radiates a dread aura, dealing %s to enemies within %s range every %s seconds and slowing them by %s%%.",
	HERO_ROOM_VOODOO_WITCH_DEATHAURA_NAME = "Dread Aura",
	HERO_ROOM_VOODOO_WITCH_DEATHSKULL_DESC = "When a Laughing Skull finishes its task it smashes into an enemy, dealing %s.",
	HERO_ROOM_VOODOO_WITCH_DEATHSKULL_NAME = "Bone Sacrifice",
	HERO_ROOM_VOODOO_WITCH_LAUGHINGSKULLS_DESC = "The Laughing Skulls attack an enemy every %s seconds, dealing %s, for up to %s attacks.",
	HERO_ROOM_VOODOO_WITCH_LAUGHINGSKULLS_NAME = "Laughing Skulls",
	HERO_ROOM_VOODOO_WITCH_VOODOOMAGIC_DESC = "%sThe witch casts voodoo magic, slowing up to %s enemies by %s%% for %s seconds and dealing %s to them.",
	HERO_ROOM_VOODOO_WITCH_VOODOOMAGIC_NAME = "Voodoo Magic",
	HERO_ROOM_WILBUR_BOX_DESC = "%sWilbur places %s walking bombs. When a walking bomb explodes it deals %s to enemies within %s range.",
	HERO_ROOM_WILBUR_BOX_NAME = "Walking Bombs",
	HERO_ROOM_WILBUR_MISSILE_DESC = "%sWilbur fires %s missiles, each dealing %s to enemies within %s range.",
	HERO_ROOM_WILBUR_MISSILE_NAME = "Missiles",
	HERO_ROOM_WILBUR_SMOKE_DESC = "%sWilbur creates a fog beneath himself lasting %s seconds that sets the movement speed of enemies within %s range to x%s%%.",
	HERO_ROOM_WILBUR_SMOKE_NAME = "Fog",
	HERO_ROOM_WILBUR_ULTIMATE_DESC = "%sWilbur summons %s drones to help fight, staying %s seconds. The drones acquire targets anywhere on the map, attacking every %s seconds up to %s times, each dealing %s.",
	HERO_ROOM_WILBUR_ULTIMATE_NAME = "Drone Swarm",
	HERO_ROOM_WITCH_BERSERKER_2_DESC = "%sWhen blocking an enemy, Strega teleports backwards, reducing all other skill cooldowns by 2 seconds and leaving a decoy behind. The decoy has %s health and explodes when destroyed, stunning nearby enemies for %s seconds.",
	HERO_ROOM_WITCH_BERSERKER_2_NAME = "Dazzling Decoy",
	HERO_ROOM_WITCH_BERSERKER_3_DESC = "%sStrega summons %s black cats to fight enemies for %s seconds. Each cat has %s and deals %s per attack.",
	HERO_ROOM_WITCH_BERSERKER_3_NAME = "Night Furies",
	HERO_ROOM_WITCH_BERSERKER_4_DESC = "%sStrega throws a big bottle of potion at the path, dealing %s and setting the movement speed of enemies in range to x%s%% for %s seconds.",
	HERO_ROOM_WITCH_BERSERKER_4_NAME = "Sticky Potion",
	HERO_ROOM_WITCH_BERSERKER_5_DESC = "%sStrega teleports up to %s enemies within %s range back along the path %s nodes and puts them to sleep for %s seconds.",
	HERO_ROOM_WITCH_BERSERKER_5_NAME = "Drowsy Return",
	HERO_ROOM_WITCH_BERSERKER_DESC = "%sStrega turns an enemy below %s health into a pumpkin for %s seconds. The pumpkin inherits %s%% of the enemy's health, has zero resistances and a movement speed of %s.",
	HERO_ROOM_WITCH_BERSERKER_NAME = "Pumpkin Magic",
	HERO_ROOM_WIZARD_ARCANETORRENT_DESC = "The old mage loves showing off in front of the youngsters. For every mage tower on the field Nivus's damage is raised by %s%%. This bonus also applies to Magic Missile and Disintegrate.",
	HERO_ROOM_WIZARD_ARCANETORRENT_NAME = "Spell Torrent",
	HERO_ROOM_WIZARD_CHAINSPELL_DESC = "%sNivus's basic attacks ricochet %s extra times.",
	HERO_ROOM_WIZARD_CHAINSPELL_NAME = "Chain Reaction",
	HERO_ROOM_WIZARD_DISINTEGRATE_DESC = "%sNivus uses the power of knowledge to disintegrate up to %s enemies whose total health is under %s.",
	HERO_ROOM_WIZARD_DISINTEGRATE_NAME = "Disintegrate",
	HERO_ROOM_WIZARD_MAGICMISSILE_DESC = "%sNivus fires %s magic missiles that track enemies anywhere on the map, each dealing %s.",
	HERO_ROOM_WIZARD_MAGICMISSILE_NAME = "Magic Missile",
	HERO_ROOM_WUKONG_BERSERKER_2_DESC = "%sSun Wukong creates 2 hair monkeys to fight beside him, each with %s, staying %s seconds and dealing %s per attack.",
	HERO_ROOM_WUKONG_BERSERKER_2_NAME = "Hair Clones",
	HERO_ROOM_WUKONG_BERSERKER_3_DESC = "%sSun Wukong throws his staff into the air and creates %s copies that fall on enemies, each dealing %s to enemies within %s range and stunning them for %s seconds.",
	HERO_ROOM_WUKONG_BERSERKER_3_NAME = "Pole Barrage",
	HERO_ROOM_WUKONG_BERSERKER_4_DESC = "%sSun Wukong grows his staff to the size of the sky and crushes one enemy to death, dealing %s to enemies within %s range.",
	HERO_ROOM_WUKONG_BERSERKER_4_NAME = "Jingu Bang Technique",
	HERO_ROOM_WUKONG_BERSERKER_5_DESC = "%sThe white dragon descends from the sky, dealing %s in total and leaving a slowing area that sets enemy movement speed to x%s%% for %s seconds. Casting this skill fully restores Wukong's health.",
	HERO_ROOM_WUKONG_BERSERKER_5_NAME = "The White Dragon",
	HERO_ROOM_WUKONG_BERSERKER_DESC = "Zhu Bajie always follows Sun Wukong into battle. He has %s, deals %s per attack and has a %s%% chance to deal %s-%s physical damage to enemies within %s range.",
	HERO_ROOM_WUKONG_BERSERKER_NAME = "Zhu's Apprentice",
	HERO_ROOM_XIN_DARING_STRIKE_DESC = "%sXin becomes invulnerable, blinks in front of the enemy with the highest health and strikes it bravely, dealing %s. Xin can blink to any position, leaving a clone behind to briefly block enemies in his place.",
	HERO_ROOM_XIN_DARING_STRIKE_NAME = "Daring Strike",
	HERO_ROOM_XIN_INSPIRE_DESC = "%sXin becomes briefly invulnerable and roars, multiplying nearby friendly units' damage by %s for %s seconds.",
	HERO_ROOM_XIN_INSPIRE_NAME = "Inspire",
	HERO_ROOM_XIN_MIND_OVER_BODY_DESC = "%sWhen Xin's remaining health falls below %s%%, he drinks the panda brew and enters Mind over Body for %s seconds. In that state his damage is raised by %s, he restores %s health every %s seconds, and he quickly clears poison, stun, bleeding and similar effects. Leaving Mind over Body reduces the cooldowns of Panda Style, Daring Strike and Inspire by 10%%. While in Mind over Body each basic attack has a 50%% chance to speed up the cooldowns of Panda Style, Daring Strike and Inspire by 10%%. At any time Xin's basic attacks have a 50%% chance to speed up Mind over Body's cooldown by 10%%.",
	HERO_ROOM_XIN_MIND_OVER_BODY_NAME = "Mind over Body",
	HERO_ROOM_XIN_PANDA_STYLE_DESC = "%s Xin performs Panda Style (a butt slam), dealing %s to enemies within %s range.",
	HERO_ROOM_XIN_PANDA_STYLE_NAME = "Panda Style",
	HERO_ROOM_XIN_ULTIMATE_DESC = "%sXin summons %s disciples to help; each elbows the enemy %s times before leaving, each elbow dealing %s.",
	HERO_ROOM_XIN_ULTIMATE_NAME = "Pandamonium",
	HERO_SPACE_ELF_DESCRIPTION = "\"To understand the dark, you must first step into it.\" For years the void mage Selien was shunned by her fellows for meddling with unknown otherworldly powers. Even so, she has always used her power with restraint, ready to act when she is needed.",
	HERO_SPACE_ELF_NAME = "Therien",
	HERO_SPACE_ELF_SPECIAL = "Astral Reflection, Void Rift, Black Aegis, Space Warp, Cosmic Prison",
	HERO_SPIDER_DESCRIPTION = "Spydyr is the last living member of a group of Twilight Elves tasked with annihilating the Spider Queen's Cult. Adding shadow magic to her unmatched hunting prowess, she is feared as one of the deadliest assassins across all kingdoms.",
	HERO_SPIDER_NAME = "Spydyr",
	HERO_SPIDER_SPECIAL = "Assassinate, Web Bind, Tunnel Passage, Hunter's Instinct, Spider Queen's Descent",
	HERO_STEAMFRIGATE_NAME = "The Black Corsair",
	HERO_STEAM_FRIGATE_NAME = "The Black Corsair",
	HERO_TANK_DESCRIPTION = "After countless years of development, one prototype after another ended in ruin. In the end only this one Doom Tank remained. No army dares face such a harbinger of destruction.",
	HERO_TANK_EXPENDABLES_NAME = "Expendables",
	HERO_TANK_NAME = "Doom Tank SG-11",
	HERO_TANK_SPECIAL = "Spiky Slug, Blazing Missiles, Ground Pound, Expendables, Scorching Cannon, Valkyrie's Call",
	HERO_THOR_DESCRIPTION = "Thunder made flesh, this gigantic demigod wields a warhammer enchanted with the power of lightning and thunder. He is the son of the Storm God, and a trusted friend of King Denas.",
	HERO_THOR_NAME = "Thor",
	HERO_THOR_SPECIAL = "Mjolnir, Thunderclap",
	HERO_TRAMIN_DESCRIPTION = "The brilliantly sharp-witted Tramin was the mastermind behind the Warmongers' finest inventions, and is now one of the most indispensable figures in Vez'nan's forces. Generous research funding lets him exercise his talents freely, and his results fully justify the investment.",
	HERO_TRAMIN_NAME = "Master Tramin",
	HERO_TRAMIN_SPECIAL = "Self-Destruct Bot, Nitro Dash, Flashbang, Rocket Barrage, Mad Bomber, Rocket Jump",
	HERO_VAMPIRESS_DESCRIPTION = "A powerful red-haired vampire, once the daughter of the vampire prince Vasile and now the lover of the demon hunter Dante.",
	HERO_VAMPIRESS_NAME = "Lucrezia",
	HERO_VAMPIRESS_SPECIAL = "Life Drain, Crimson Dance, Slaughter Growth, Blood Offspring",
	HERO_VAN_HELSING_DESCRIPTION = "A lone, unsmiling demon hunter. In life and in death he is our beacon of light, fighting unceasingly for the justice in his heart, never giving up.",
	HERO_VAN_HELSING_NAME = "Dante",
	HERO_VAN_HELSING_SPECIAL = "Silver Bullets, Deadly Rapid Fire, Power of the Ruins, Holy Water Bomb, Beacon of Light",
	HERO_VENOM_DESCRIPTION = "When the cultists failed to turn the mercenary Grimson into an abomination, they imprisoned him and left him to rot. That agony unexpectedly gave Grimson the power to transform (and an unfathomable stomach), which he used to escape the cult's grip. He swore that one day he would return and take his revenge.",
	HERO_VENOM_NAME = "Grimson",
	HERO_VENOM_SPECIAL = "Heartseeker, Inner Beast, Deadly Spikes, Renew Flesh, Creeping Death",
	HERO_VESPER_DESCRIPTION = "Proficient with both sword and bow, Vesper won his place as commander of the Linirean forces. After Linirea fell and King Denas disappeared, he gathered all the troops he could and started a crusade to bring back the former ruler.",
	HERO_VESPER_NAME = "Vesper",
	HERO_VESPER_SPECIAL = "Arrow to the Knee, Ricochet, Disengage, Martial Flourish, Arrow Storm",
	HERO_VEZNAN_DESCRIPTION = "A mage of legend and a close friend of Denas. He sought arcane power in his youth, then studied dark magic and made a pact with a demon. Power is power!",
	HERO_VEZNAN_NAME = "Vez'nan",
	HERO_VEZNAN_SPECIAL = "Soul Split, Cage of Pain, Arcane Nova, Demon Pact",
	HERO_VOODOO_WITCH_DESCRIPTION = "A witch of the Tukuya tribe, skilled in the supernatural: she can seal enemies' souls inside skulls and turn them into a source of her power.",
	HERO_VOODOO_WITCH_NAME = "Voodoo Witch",
	HERO_VOODOO_WITCH_SPECIAL = "Laughing Skulls, Bone Sacrifice, Skeleton Dance, Dread Aura, Voodoo Magic",
	HERO_WILBUR_DESCRIPTION = "A respectable adventurer! A genius inventor! Wilbur will be our eyes in the sky!",
	HERO_WILBUR_NAME = "Wilbur",
	HERO_WILBUR_SPECIAL = "Fog, Missiles, Walking Bombs, Drone Swarm",
	HERO_WITCH_DESCRIPTION = "While she loves to surprise strangers passing through the Faery Forest with fun and harmless tricks, those who pose a threat to the woods or her fellow gnomes soon find that her playful smile hides a relentless witch to be reckoned with. ",
	HERO_WITCH_NAME = "Stregi",
	HERO_WITCH_SPECIAL = "Pumpkin Magic, Dazzling Decoy, Night Furies, Sticky Potion, Drowsy Return",
	HERO_WIZARD_DESCRIPTION = "A learned and respected old mage, Vez'nan's teacher. Old as he is, he remains a powerful mage. It is said that the more young folk are watching, the stronger he performs.",
	HERO_WIZARD_NAME = "Nivus",
	HERO_WIZARD_SPECIAL = "Magic Missile, Chain Reaction, Disintegrate, Spell Torrent",
	HERO_WUKONG_DESCRIPTION = "Born of a celestial stone of Yin and Yang, Sun Wukong was gifted with strength, agility, and immortality. But the demon kings stole the spheres of power from him. Now, the legendary trickster rises to reclaim them before it is too late.",
	HERO_WUKONG_NAME = "Sun Wukong",
	HERO_WUKONG_SPECIAL = "Zhu's Apprentice, Hair Clones, Pole Barrage, Jingu Bang Technique, The White Dragon",
