	KEYBOARD_KEY_SPACE = "SPACE",
	LAST_HOOK_TARGET_NOT_INITIALIZED = "! If you see this message, screenshot it and send it to the author. target: %s, mod: %s",
	LEGAL_GOV_APPROVAL = "Ministry of Culture filing: Online Game Approval [2018] No. 0058%s",
	LEGAL_HEALTH_ADVICE = "Health advice: Resist bad games and refuse piracy. Protect yourself and beware of scams. Moderate gaming sharpens the mind; addiction ruins the body. Manage your time and enjoy a healthy life.",
	LEVEL_1000_HISTORY = "Note: path 2 is the straight line below",
	LEVEL_1000_TITLE = "Cricket Fight Stage 1",
	LEVEL_101_HISTORY = "We have been scouring the southern forests for months unsuccessfully as King Denas is nowhere to be found. In the meantime we befriended the Arboreans, spirits of nature and met their warring neighbors, the Wildbeasts, who keep attacking us on sight.\nLet's get this fight done so we can keep looking for the King.",
	LEVEL_101_TITLE = "Sea of Trees",
	LEVEL_102_HISTORY = "Be alert, word reached us by wisp! The Heart of the Forest is under attack! We must go back and help the Arboreans. Some Dark Army forces will join us on the battlefield, so keep an eye open. We might be in the same boat for now, but that could change at any moment.",
	LEVEL_102_TITLE = "Guardian Gate",
	LEVEL_103_HISTORY = "We made it back to the Heart in the nick of time, but the Wildbeasts are already passing through. Look alive and fortify your positions! Protect the Heart at all costs or the forest and the Arboreans will surely perish.",
	LEVEL_103_TITLE = "Heart of the Forest",
	LEVEL_104_HISTORY = "Now that the Heart of the Forest is safe we must regroup and press the advantage. It is time to take the fight to Wildbeast territory. Take the troops to the treetops of the forest and look for their encampment from above.",
	LEVEL_104_TITLE = "Emerald Treetops",
	LEVEL_105_HISTORY = "Thanks to your efforts taking the high ground, we located the Wildbeast encampment in some ancient ruins beyond the limits of the forest. Lead the forces towards their territory and be wary of their tactics. We might have won another battle, but this is far from done.",
	LEVEL_105_TITLE = "Derelict Outskirts",
	LEVEL_106_HISTORY = "We might have the upper hand against the Wildbeasts, but we still have to face their leader, Goregrind. The self proclaimed Wildbeast King is a mighty foe, so don't let yourself be fooled by his antics or you will meet your end under his tusks.",
	LEVEL_106_TITLE = "Beast Lair",
	LEVEL_107_HISTORY = "Following the trail of the cultists who assisted the Wildbeasts in razing part of the forest, we arrive at a desolate place where we suspect the Cult is carrying out their strange plans. We need to be cautious, as we don't know exactly what we're up against... but they seem to have a few tricks under their hoods.",
	LEVEL_107_TITLE = "Bleak Valley",
	LEVEL_108_HISTORY = "As we made our way into cultist territory, we arrived in a set of huge caverns full of crystals that resonate with strange magic. The Cult is mining these crystals, surely to use them as a power source. To what ends, we do not know, but disrupting their activities is a good way to cause chaos in their ranks.",
	LEVEL_108_TITLE = "Crimson Mines",
	LEVEL_109_HISTORY = "These tunnels' twists and turns are maddening but we know we are on the right path as cultist activity keeps increasing. As we progress further we face new kinds of horrors, which begs the question of how deep the corruption runs within the Cult's ranks.",
	LEVEL_109_TITLE = "Wicked Crossing",
	LEVEL_10_HEROIC = "Heroic Description 10",
	LEVEL_10_HISTORY = "We have arrived at the dreadful realm of Valardul. This is a barren and forsaken land, where the wretched souls of the departed find no solace.\n\nPray to the gods that this place does not take its toll on your men's spirits...",
	LEVEL_10_IRON = "Iron Description 10",
	LEVEL_10_IRON_UNLOCK = "no artillery",
	LEVEL_10_MODES_UPGRADES = "lvl 4 max",
	LEVEL_10_TITLE = "The Wastes",
	LEVEL_110_HISTORY = "It turns out that the Cult is using the mined crystals to build an ominous looking artifact right out of the canyon. It buzzes with strange energy and the air surrounding the place feels heavy. We have to make sure it is destroyed before advancing.",
	LEVEL_110_TITLE = "Temple Courtyard",
	LEVEL_111_HISTORY = "We finally made it out of the canyons but there is still a long way to go. We now stand in front of a giant portal embedded with crystals as Seeress Mydrias finishes her rituals. What will come from beyond we do not know, but we still stand ready. Brace yourselves!",
	LEVEL_111_TITLE = "Canyon Plateau",
	LEVEL_112_HISTORY = "With Denas back on our side, we crossed the portal into the unknown. This strange world looks like a twisted reflection of Linirea, but one swallowed by blight. Mind your step, something worse than the Cult lurks in the dark.",
	LEVEL_112_TITLE = "Withered Farmlands",
	LEVEL_113_HISTORY = "The familiar sight of the Stormcloud Temple looms on the horizon. The path is clear enough, follow the stench and corruption as they grow and we will find the source of it all. We just have to survive the twisted horrors that seem to emerge from the earth itself.",
	LEVEL_113_TITLE = "Desecrated Temple",
	LEVEL_114_HISTORY = "These damned creatures seem to spawn out of nowhere! The troops are restless, everything we touch looks alive and ready to attack us, as if the land itself was fighting against us with all its might. Seeress Mydrias and her minions must be near.",
	LEVEL_114_TITLE = "Corrupted Valley",
	LEVEL_115_HISTORY = "We emerged from the valley victorious and now the only thing standing between us and the Overseer is Mydrias herself. We saw what she was capable of back in the canyons, but here, under the sight and might of her master, she has the upper hand. Not that the odds ever stopped us before. Look alive!",
	LEVEL_115_TITLE = "Overseer's Spire",
	LEVEL_116_HISTORY = "Mydrias is gone, but a far greater enemy - the all-seeing Eye - still waits for us. This is our last chance to end the cult and the invasion for good. If we cannot stand united to the very end, whatever comes next will be meaningless. Let the final battle begin! (Heroic and Iron modes are not ready yet - please do not play them.)",
	LEVEL_116_TITLE = "Summit of Desire",
	LEVEL_117_HISTORY = "The once playful wonderland forest is now filled with malice and dread. Reports say packs of undead elven warriors and specters roam this land, attacking travelers and corrupting the forest. General, we must investigate.",
	LEVEL_117_TITLE = "Misty Ruins",
	LEVEL_118_HISTORY = "Deepleaf Outpost reports that the elves can barely hold back the undead army. We must hurry to support the elven troops and their captain, Eridan, before it is too late. Once the outpost is secure we can push on to the root of this invasion.",
	LEVEL_118_TITLE = "Deepleaf Outpost",
	LEVEL_119_HISTORY = "Eridan has fought himself to exhaustion. He points us toward the Fallen Temple, where a mage who calls himself Vanier, Master of Souls, has awakened the undead army to raze the continent. We must stop him at any cost!",
	LEVEL_119_TITLE = "Fallen Temple",
	LEVEL_11_HEROIC = "Heroic Description 11",
	LEVEL_11_HISTORY = "Threading through the Forsaken Valley will not be an easy task! We are near the end of our journey, and although our men are tired, they are filled with honorable purpose.\n\nBut beware... this is a land riddled with Rock and Fire Titans... best not to upset them!",
	LEVEL_11_IRON = "Iron Description 11",
	LEVEL_11_IRON_UNLOCK = "no artillery\nno archer",
	LEVEL_11_MODES_UPGRADES = "lvl 5 max",
	LEVEL_11_TITLE = "Forsaken Valley",
	LEVEL_120_HISTORY = "We have received an urgent plea from the treants at the forest's edge: they are under relentless attack by the crocodile folk and cannot last much longer. Be careful, General - the crocodile folk have plenty of schemes in their bellies.",
	LEVEL_120_TITLE = "Arborean Village",
	LEVEL_121_HISTORY = "The village is safe. The treants tell us that even before the attack they sensed the ancient seal was about to fail - which is probably why the crocodile folk struck so suddenly. Following that lead, we pushed into the heart of the swamp and stumbled upon an ancient treant stone circle that looks like a nest... the nest of something enormous.",
	LEVEL_121_TITLE = "Sunken Ruins",
	LEVEL_122_HISTORY = "At the ancient temple our worst fears came true. The wards that have long protected the world and sealed away Gluttony, the world-devouring crocodile, have all but collapsed; only a few desperate treant shamans still hold them together. General, stop the Devourer of Worlds, or the whole kingdom will fall into his insatiable jaws.",
	LEVEL_122_TITLE = "Ravenous Gorge",
	LEVEL_123_HISTORY = "Scouts report an unusual landslide in the nearby mountains. Further investigation shows the culprits are a band of unfamiliar dwarves assembling a giant robot on the mountain's southern face. General, you must go and investigate.",
	LEVEL_123_TITLE = "Darksteel Gate",
	LEVEL_124_HISTORY = "Dwarves have always been known as inventors, but this clan, calling themselves 'Darksteel', has become obsessed with metal to the point of madness - even Bogur's dwarves pale beside them, forging steel armaments furnace after furnace. Who is behind this? We must find out!",
	LEVEL_124_TITLE = "Fanatical Assembly Plant",
	LEVEL_125_HISTORY = "As we feared, only the interior of this mountain could house forges capable of building a robot of that size. How many dwarves are in here? So many bar our way, yet more keep forging and welding. Stranger still, they all look exactly alike. Something is being hidden here.",
	LEVEL_125_TITLE = "Colossal Core",
	LEVEL_126_HISTORY = "Moving in and out of the mountain, we reach a room full of great vats - and what is inside them is astonishing. No wonder these dwarves are so numerous and so identical in skill and appearance. They are all the same dwarf: Grimbeard! He uses vile science to mass-produce copies of himself. General, we must put a stop to this!",
	LEVEL_126_TITLE = "Cloning Chamber",
	LEVEL_127_HISTORY = "Our forces have all but dismantled the Darksteel conspiracy within this mountain, but if Grimbeard still walks free it will all be for nothing. He must be completing the final work, preparing to activate the robot's head. General, lead the troops to the summit - and pray that this time we face the real Grimbeard.",
	LEVEL_127_TITLE = "Dome of Dominion",
	LEVEL_128_HISTORY = "Following the trail our scouts left, we found traces of those persistent cultists. It seems they have found a new god to worship - an evil, web-spinning monster... Cultists plus spiders? Nothing good ever comes of that!",
	LEVEL_128_TITLE = "Defiled Temple",
	LEVEL_129_HISTORY = "The deeper we go, the more clearly we feel that this horror has lurked in the dark for a long time, waiting for the right moment to strike. Webs thicken all around, uncanny darkness presses on our backs - I would say the heart of the nest is near.",
	LEVEL_129_TITLE = "Breeding Chamber",
	LEVEL_12_HEROIC = "Heroic Description 12",
	LEVEL_12_HISTORY = "Our troops gather around the dread wizard Vez'nan's tower. It is time for a reckoning... time for the final fray. This is the ultimate battle for our kingdom's safety. Every step has brought us to this moment; and there is no turning back.\n\nNow it's time to show our mettle!",
	LEVEL_12_IRON = "Iron Description 12",
	LEVEL_12_IRON_UNLOCK = "no artillery",
	LEVEL_12_MODES_UPGRADES = "lvl 5 max",
	LEVEL_12_TITLE = "The Dark Tower",
	LEVEL_130_HISTORY = "At last we reached the lair of their so-called goddess: a ruined, long-abandoned temple, ready to collapse under the weight of its own forgotten history. A god abandoned by the world deserves no better throne. These vermin must be wiped out, every last one.",
	LEVEL_130_TITLE = "Forgotten Throne",
	LEVEL_131_HISTORY = "After all these campaigns, the kingdom is at peace again. Now there is nothing to do but listen to the waves on the shore, set up a game of Go, and wait for an old friend. Yet even with calm waters before me, I fear this peace will not last long...",
	LEVEL_131_TITLE = "Immortal Monkey Forest",
	LEVEL_132_HISTORY = "Our army pursued deep into the volcano and found an abandoned ancient temple that once housed the worship of flame.\n\nYet the crimson dragon who guards the lava abyss, once content to keep to itself, is now restless and brimming with rage. Such a change must be Red Boy's sorcery clouding its mind.",
	LEVEL_132_TITLE = "Blaze Dragon Cavern",
	LEVEL_133_HISTORY = "After a hard fight with Red Boy, our army pushed on to Ragewind Isle. The moment we landed, hurricane winds rose and coiled like pythons. This island is terribly dangerous, but it is the only road to Princess Iron Fan's palace! Steady yourselves - the storm is coming!",
	LEVEL_133_TITLE = "Ragewind Isle",
	LEVEL_134_HISTORY = "Every hardship so far has been the work of the princess's iron fan. We broke through the storm and reached the eye of the wind. The pavilions here stand untouched; beautiful as it is, this place hides deadly intent - do not relax your guard! Even the Demon King's household will not stand in our way!",
	LEVEL_134_TITLE = "Eye of the Storm",
	LEVEL_135_HISTORY = "The great battle is at hand! The Bull Demon King lords over the Golden City, and what remains of our army must break him head-on with wits and courage! We must cut out this evil before he lays hands on the spirit pearl.\nFor the land and the realm, for all living things - soldiers of the Alliance, form up and purge the demon!",
	LEVEL_135_TITLE = "Demon King's Fortress",
	LEVEL_136_HISTORY = "Sky explorers brought troubling news: far above the kingdom they found a mysterious magical portal, long sealed and carved with ancient script.\nAlthough the ancient words carry a stern warning - 'Do not enter the Cloud Realm' - the King and Vez'nan have both decided to go and learn the truth.",
	LEVEL_136_TITLE = "Dragon Gate",
	LEVEL_137_HISTORY = "We have passed through the portal and stepped into the Cloud Realm. Our mission is clear: aid Orion and protect the last Queen's Dragon Eggs. To do so we must reach the Warden Fortress - an ancient stronghold held by the diminutive but battle-hardened Wardens.\nSuddenly a violent roar echoes ahead. We must hurry to the rescue.",
	LEVEL_137_TITLE = "Warden Fortress",
	LEVEL_138_HISTORY = "After a hard fight we have retaken the Warden Fortress, and can now advance on the Core Sanctuary - the holy ground guarded by the moon dragon Lunalis, keeper of the Queen's Dragon Eggs. Time is short; let us hope we are still in time.",
	LEVEL_138_TITLE = "Core Sanctuary",
	LEVEL_139_HISTORY = "The death of Lunalis and the loss of the Queen's Dragon Eggs struck our morale hard, and gloom hangs over the troops. Then King Denas spoke, and the soldiers' will to fight the Draconians burned bright again.\nWe have now reached a vast volcanic crater, the source of the monster army. The moment for an all-or-nothing strike has come: this battle will take us straight to the heart of the evil and root it out!",
	LEVEL_139_TITLE = "Draconian Breeding Grounds",
	LEVEL_13_HEROIC = "Heroic Description 13",
	LEVEL_13_HISTORY = "General! We have need of you and your brave men! The late Vez'nan's causes trouble from beyond the grave. While you were battling him, he sent one of his hordes to wake up one of the dreaded spider queens, Sarelgaz!\n\nWe thought the spider queens would never wake up again, but Sarelgaz has, and with her powers over darkness she's taken control of Vez'nan's remaining troops. You must vanquish them, and slay Sarelgaz!",
	LEVEL_13_IRON = "Iron Description 13",
	LEVEL_13_IRON_UNLOCK = "no artillery\nno mage",
	LEVEL_13_MODES_UPGRADES = "lvl 5 max",
	LEVEL_13_TITLE = "Sarelgaz's Lair",
	LEVEL_140_HISTORY = "The end approaches. The Warden mages have sensed evil descending on the ancient sacrificial grounds. Tiransor is trying to draw the essence of royal blood from the dragon eggs and become the undisputed king of dragons. Our scouts will confirm the exact position of Tiransor and his forces, and we must muster for the final battle.\nAlliance, assemble!",
	LEVEL_140_TITLE = "Crown of the Cloud Realm",
	LEVEL_14_HEROIC = "Heroic Description 14",
	LEVEL_14_HISTORY = "Defender of Linirea! The realm is at peace, but evil does not rest! Our agents report that the Ruins of Acaroth have been invaded by orc and goblinoid hordes.\n\nGul'Thak, a new orcish warlord has taken advantage of the power vacuum left by Vez'nan, and his forces are terrorizing the area.\n\nYou must drive these invaders away from the ruins!",
	LEVEL_14_IRON = "Iron Description 14",
	LEVEL_14_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_14_MODES_UPGRADES = "lvl 5 max",
	LEVEL_14_TITLE = "Ruins Of Acaroth",
	LEVEL_15_HEROIC = "Heroic Description 15",
	LEVEL_15_HISTORY = "Summon your troops, General! The forces of darkness are relentless in their attacks against our beloved kingdom, and we must take action. Reports indicate that the area known as the Rotten Forest is indeed rotten; as a portal to the netherworld has opened in the midst of the woods.\n\nThe dead find no rest in this forest, and vegetation turns against any who wander into it. You must lead your forces into the Rotten Forest and get to the root of the problem!",
	LEVEL_15_IRON = "Iron Description 15",
	LEVEL_15_IRON_UNLOCK = "no archers\nno artillery",
	LEVEL_15_MODES_UPGRADES = "lvl 5 max",
	LEVEL_15_TITLE = "Rotten Forest",
	LEVEL_16_HEROIC = "Heroic Description 15",
	LEVEL_16_HISTORY = "General, you must once more rouse your troops, and protect our kingdom from its enemies! Scout reports indicate that a vicious band of delinquents is amassing far into the depths of Hushwood. Yes, Hushwood, where few of our citizens dare wander... but you are no mere citizen!\n\nLead your forces into the woods, and vanquish these miscreants. Make them rue the day they decided to embark on a life of crime!",
	LEVEL_16_IRON = "Iron Description 15",
	LEVEL_16_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_16_MODES_UPGRADES = "lvl 5 max",
	LEVEL_16_TITLE = "Hushwood",
	LEVEL_17_HEROIC = "Heroic Description 15",
	LEVEL_17_HISTORY = "Great job! You've managed to put those dastardly delinquents on the run. The combined might of your units has crushed most of their roaming forces, but they're fleeing deeper into the forest. We have reason to believe that they have a secret lair inside the woods, and that's where they keep their loot.\n\nPursue them, draw them out of their lair, and recover the loot. Forewarned, criminals this successful probably have a cunning escape plan!",
	LEVEL_17_IRON = "Iron Description 16",
	LEVEL_17_IRON_UNLOCK = "no mages\nno artillery",
	LEVEL_17_MODES_UPGRADES = "lvl 5 max",
	LEVEL_17_TITLE = "Bandit's Lair",
	LEVEL_18_HEROIC = "Heroic Description 15",
	LEVEL_18_HISTORY = "Pack your winter gear, troops; we're heading for the Glacial Heights! The locals have reported some disturbances, and our King commands we march upon the heights to investigate these reports. Watch out, because the heights have become the icy tomb of many an unprepared explorer.\n\nYou might freeze to death, that is, if the savage Ha'Kraj trolls don't get you first!",
	LEVEL_18_IRON = "Iron Description 15",
	LEVEL_18_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_18_MODES_UPGRADES = "lvl 5 max",
	LEVEL_18_TITLE = "Glacial Heights",
	LEVEL_19_HEROIC = "Heroic Description 15",
	LEVEL_19_HISTORY = "We now know the northern disturbances were caused by Ulguk-Hai, the Troll Warlord! This despicable beast has united all the Ha'Kraj Troll clans under his blood-red banner! If we don't stop him, his forces will descend from the North and menace the good citizens of Linirea.\n\nPrepare to fight the amassed ferocity of the Ha'Kraj nation, and face their vicious leader in his home turf!",
	LEVEL_19_IRON = "Iron Description 15",
	LEVEL_19_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_19_MODES_UPGRADES = "lvl 5 max",
	LEVEL_19_TITLE = "Ha'Kraj Plateau",
	LEVEL_1_HEROIC = "Heroic Description 1",
	LEVEL_1_HISTORY = "Greetings, noble and heroic warrior! As a General of His Majesty's forces, King Denas requires your services.\n\nThe inhabitants of the city of Southport have reported attacks by highwaymen and other roaming outlaws. You must take a battalion to Southport to bolster the city's defenses.\n\nGood luck, General!",
	LEVEL_1_IRON = "Iron Description 1",
	LEVEL_1_IRON_UNLOCK = "no archer\nno mage",
	LEVEL_1_MODES_UPGRADES = "lvl 1 max\nNo Heroes",
	LEVEL_1_TITLE = "Southport",
	LEVEL_201_HISTORY = "General, I was sent back in time to warn the Linirean King of the fate of the world at the hands of Vez'nan, the Dark Wizard.\n\nI see that even in these times the citadel is being sieged by bandits, so let's first get rid of this threat before marching forward!",
	LEVEL_202_HISTORY = "Our army is in no shape of making it through the Bandit's Lair east of the castle, we should go west to recruit some allies in the Arcane Academy.\n\nThey too seem to be facing the Bandit threat! After assisting in the defense, they will surely hear our proposal.",
	LEVEL_203_HISTORY = "The local farmers tell us they have been under attack from what they refer to as the \"Shadow Order\" for months, but even their messengers have disappeared in ambushes.\n\nGeneral, we must stop and help them even if it delays our mission. It is the right thing to do.",
	LEVEL_201_TITLE = "Linirean Castle",
	LEVEL_202_TITLE = "ARCANE ACADEMY",
	LEVEL_203_TITLE = "RAIDED FARMLANDS",
	LEVEL_20_HEROIC = "Heroic Description 15",
	LEVEL_20_HISTORY = "Demons have ravaged our troops stationed at Vez'nan's tower, leaving a lone survivor... From his terrified mumbling we've learned that these hellish hordes rose from the depths of the Rift of Cinders. \n\nGeneral, you must secure the area, discover the true origin of this threat, and make sure we have truly prevailed over Vez'nan.",
	LEVEL_20_IRON = "Iron Description 15",
	LEVEL_20_IRON_UNLOCK = "no mages",
	LEVEL_20_MODES_UPGRADES = "lvl 5 max",
	LEVEL_20_TITLE = "Pit Of Fire",
	LEVEL_21_HEROIC = "Heroic Description 15",
	LEVEL_21_HISTORY = "We face Moloch, one of the Great Demon Lords. Our sages have discovered that it was he who opened the portal, leading to Pandaemonium, a fearsome hellish plane. \n\nYou have sworn to follow your King even into hell itself... and that's exactly where you're going...",
	LEVEL_21_IRON = "Iron Description 15",
	LEVEL_21_IRON_UNLOCK = "no artillery",
	LEVEL_21_MODES_UPGRADES = "lvl 5 max",
	LEVEL_21_TITLE = "Pandaemonium",
	LEVEL_22_HEROIC = "Heroic Description 15",
	LEVEL_22_HISTORY = "There's no rest for the wicked... and thus, none for the good guys either. A messenger eagle has arrived from the Elven garrison in the Rotten Forest. The woods are still corrupted by evil, and our Elven allies are repelling attacks by horrible monsters. \n\nA new dark power is rising, attempting to expand its domain beyond the forest's depths. Hurry, General, we must go assist our Elven friends, and forever vanquish evil from that ancient forest!",
	LEVEL_22_IRON = "Iron Description 15",
	LEVEL_22_IRON_UNLOCK = "no archers\nno artillery",
	LEVEL_22_MODES_UPGRADES = "lvl 5 max",
	LEVEL_22_TITLE = "Fungal Forest",
	LEVEL_23_HEROIC = "Heroic Description 23",
	LEVEL_23_HISTORY = "General, our Kingdom is in peril once again! King Banesti, of neighbouring Niroma was on his way here for the \"Great Tournament of the Kingdoms\", but he was captured at Mournful Valley. His people would never forgive us if something happened to the elderly sovereign, it could lead to war between our two realms!\n\nThe fastest route to the valley is, I'm afraid, the Royal Roadway, through the infamous Rotwick.",
	LEVEL_23_IRON = "Heroic Description 23",
	LEVEL_23_IRON_UNLOCK = "no barracks\nno artillery",
	LEVEL_23_MODES_UPGRADES = "lvl 5 max",
	LEVEL_23_TITLE = "Rotwick",
	LEVEL_24_HEROIC = "Heroic Description 24",
	LEVEL_24_HISTORY = "We'll look back fondly on that ambush at Rotwick, for now the Royal Road brings us to the Necropolis!\n\nAs our men make their way through ancient crypts and ransacked tombs, they grow restless with the staggering amount of open graves. The preternatural silence only makes it worse, as it is undoubtedly but a preamble to another attack by the forces of darkness.",
	LEVEL_24_IRON = "Heroic Description 24",
	LEVEL_24_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_24_MODES_UPGRADES = "lvl 5 max",
	LEVEL_24_TITLE = "Ancient Necropolis",
	LEVEL_25_HEROIC = "Heroic Description 25",
	LEVEL_25_HISTORY = "You will not find many places viler than the disgusting bog we must cross to get to Lord Blackburn's castle.\n\nGathered witches fill the air with their unseemly chanting, which meshes perfectly with the cries of wild, hungry animals. These are the beings that serve a once great, noble knight. From the putrid waters, dozens of dead bodies stare at us with empty eyes...",
	LEVEL_25_IRON = "Heroic Description 25",
	LEVEL_25_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_25_MODES_UPGRADES = "lvl 5 max",
	LEVEL_25_TITLE = "Nightfang Swale",
	LEVEL_26_HEROIC = "Heroic Description 26",
	LEVEL_26_HISTORY = "Sadness overtakes our hearts as we lay our eyes on a fallen champion. So deeply did Lord Blackburn yearn for the power to battle evil, that it corrupted him, sinking his lands into the grip of darkness. Alas, he cannot be saved; but we have arrived just in time to rescue good King Banesti from being hanged.\n\nGeneral, you hold the key to the peace between the kingdoms... defeat Lord Blackburn, and perhaps death will give him a measure of redemption!",
	LEVEL_26_IRON = "Heroic Description 26",
	LEVEL_26_IRON_UNLOCK = "no archers\nno artillery",
	LEVEL_26_MODES_UPGRADES = "lvl 5 max",
	LEVEL_26_TITLE = "Castle Blackburn",
	LEVEL_27_HEROIC = "Heroic Description 1",
	LEVEL_27_HISTORY = "Defender of Linirea!\nYour services are once more required, as evil forces are attacking the ancient stronghold of Hammerhold! It hasn't been attacked in a long time... and now it's once again under siege by nomadic desert tribes!\n\nTake command of the kingdom's forces, and defend us!",
	LEVEL_27_IRON = "Iron Description 1",
	LEVEL_27_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_27_MODES_UPGRADES = "lvl 1 max\nNo Heroes",
	LEVEL_27_TITLE = "Hammerhold",
	LEVEL_28_HEROIC = "Heroic Description 2",
	LEVEL_28_HISTORY = "In the midst of all the confusion, Lord Malagar stole the powerful Hammer of Ages from Hammerhold!\n\nOur outposts east of the fortress report he's fled in that direction, and they are facing him as we speak, delaying his escape. We must hurry, General, and go to their aid!",
	LEVEL_28_IRON = "Iron Description 2",
	LEVEL_28_IRON_UNLOCK = "no archers\nno artillery",
	LEVEL_28_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_28_TITLE = "Sandhawk Hamlet",
	LEVEL_29_HEROIC = "Heroic Description 2",
	LEVEL_29_HISTORY = "Our armies have amassed under your command, as we pursue Lord Malagar across the Azsare desert!\n\nWe have followed his trail to the Sape Oasis, one of the few green spots in this wasteland. As such, the nomad tribes do not take kindly to trespassers, so don't provoke the desert's fiercest denizens, the Duskar!",
	LEVEL_29_IRON = "Iron Description 2",
	LEVEL_29_IRON_UNLOCK = "no artillery",
	LEVEL_29_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_29_TITLE = "Sape Oasis",
	LEVEL_2_HEROIC = "Heroic Description 2",
	LEVEL_2_HISTORY = "Good job! Your diligent investigations have revealed that it was not mere brigands terrorizing Southport, but organized bands of goblins and orcs!\n\nNow, their forward troops are creeping towards the defenseless rural communities North of Southport.\n\nWe must establish an efficient and swift defense!",
	LEVEL_2_IRON = "Iron Description 2",
	LEVEL_2_IRON_UNLOCK = "no barracks",
	LEVEL_2_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_2_TITLE = "The Outskirts",
	LEVEL_30_HEROIC = "Heroic Description 3",
	LEVEL_30_HISTORY = "It seems the attack at Sape Oasis was merely a distraction, and Lord Malagar has escaped towards Buccaneer's Den.\n\nWe have no choice but to cross the treacherous Dunes of Despair. There is no time to go around them, so beware of the shifting sands, as the mysterious beasts crawling through them have caused the doom of many an experienced explorer!",
	LEVEL_30_IRON = "Iron Description 3",
	LEVEL_30_IRON_UNLOCK = "no artillery\nno mage",
	LEVEL_30_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_30_TITLE = "Dunes of Despair",
	LEVEL_31_HEROIC = "Heroic Description 4",
	LEVEL_31_HISTORY = "Behold Buccaneer's Den!\nNowhere else will you find a worse collection of unruly freebooters and dastardly pirates… and nowhere but here will you find a better crew to sail the Crystal Sea.\n\nAfter greasing some dirty palms we've learned that Lord Malagar has boarded a ship towards The Gates of Nazeru. Hiring a crew, however, will have to wait, as an enemy fleet is heading toward us. Ahoy!",
	LEVEL_31_IRON = "Iron Description 4",
	LEVEL_31_IRON_UNLOCK = "no barracks\nno artillery",
	LEVEL_31_MODES_UPGRADES = "lvl 2 max",
	LEVEL_31_TITLE = "Buccaneer's Den",
	LEVEL_32_HEROIC = "Heroic Description 5",
	LEVEL_32_HISTORY = "We have arrived at the legendary Gates of Nazeru, which block passage to the lost lands. Something foul is at play here, and the troops are nervous. Not the roving enemy war bands we've seen, our men can handle those...\n\nFortunately, the Archmage Guild is here to aid us in opening the Gates, and we'll have them on our side if battle breaks out.",
	LEVEL_32_IRON = "Iron Description 5",
	LEVEL_32_IRON_UNLOCK = "no barracks\nno archers",
	LEVEL_32_MODES_UPGRADES = "lvl 3 max",
	LEVEL_32_TITLE = "Nazeru's Gates",
	LEVEL_33_HEROIC = "Heroic Description 6",
	LEVEL_33_HISTORY = "The mighty Templar Order joins us as we reach the breathtaking Crimson Valley, a name it's earned for being the Ma'qwa tribe's hunting grounds. We've established a base camp here and given the men some time off to rest and recover, but we must remain vigilant.\n\nNone of us has ever seen one of the Ma'qwa, but the rumors about them are... unsettling, to say the least.",
	LEVEL_33_IRON = "Iron Description 6",
	LEVEL_33_IRON_UNLOCK = "no artillery\nno archers",
	LEVEL_33_MODES_UPGRADES = "lvl 3 max",
	LEVEL_33_TITLE = "Crimson Valley",
	LEVEL_34_HEROIC = "Heroic Description 7",
	LEVEL_34_HISTORY = "Scouting troops inform us that Lord Malagar heads east, to the city of Ma'qwa Urqu, beyond the Za'golon river. The only way there is through the Snapvine Bridge, built long ago by the Barrington-Keynes Expedition.\n\nOur newest allies, the Tuk'va tribe, are sworn enemies of the Ma'qwa, and they warn us about the vegetation… it seems to have something of an appetite around these parts…",
	LEVEL_34_IRON = "Iron Description 7",
	LEVEL_34_IRON_UNLOCK = "no mages\nno artillery",
	LEVEL_34_MODES_UPGRADES = "lvl 3 max",
	LEVEL_34_TITLE = "Snapvine Bridge",
	LEVEL_35_HEROIC = "Heroic Description 8",
	LEVEL_35_HISTORY = "On our way to Ma'qwa Urqu, the jungle keeps getting deadlier. As if the tangled maze of roots, trees, and snapvines that have never known the sun's kiss weren't enough, something darker lurks within the thick rainforest.\n\nThe men feel as if they're being hunted by something not of this world… Almost as unsettling are the necromancers we've enlisted. However, their being against Lord Malagar's plans only stresses the urgency of stopping him.",
	LEVEL_35_IRON = "Iron Description 8",
	LEVEL_35_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_35_MODES_UPGRADES = "lvl 4 max",
	LEVEL_35_TITLE = "Lost Jungle",
	LEVEL_36_HEROIC = "Heroic Description 9",
	LEVEL_36_HISTORY = "Cast your gaze upon the ancient city of Ma'qwa Urqu, home to the sinister man-eating tribe that has become our enemy! Hear the battle drums and dark shamanic chanting that emanate from its mountaintop perch, feel the heat from that dangerous volcano; this is their place of power!\n\nTo pursue our dreaded foe, we must first get through the Ma'qwa forces surrounding the city. Good thing our Dwarven engineers and their gnomish tinkerer cousins have cooked up a mighty mechanical surprise…",
	LEVEL_36_IRON = "Iron Description 9",
	LEVEL_36_IRON_UNLOCK = "no artillery\nno mage",
	LEVEL_36_MODES_UPGRADES = "lvl 4 max",
	LEVEL_36_TITLE = "Ma'qwa Urqu",
	LEVEL_37_HEROIC = "Heroic Description 10",
	LEVEL_37_HISTORY = "We have him surrounded! The Temple of Saqra will be Lord Malagar's last stand! The Ma'qwa are even fiercer here, where they worship their crocodile-visaged deity, and their own Warlord King is leading them now.\n\nThe combined might of the Ma'qwa and their leader's magics is quite possibly the most impressive array of savagery evil might ever assembled! Fight back with all your prowess, my men, lest we end up as sacrifices to Saqra… or worse.",
	LEVEL_37_IRON = "Iron Description 10",
	LEVEL_37_IRON_UNLOCK = "no barracks\nno archers",
	LEVEL_37_MODES_UPGRADES = "lvl 4 max",
	LEVEL_37_TITLE = "Temple of Saqra",
	LEVEL_38_HEROIC = "Heroic Description 11",
	LEVEL_38_HISTORY = "It seems that the Temple of Saqra was merely the entrance to a vast underground labyrinth, carved into the mountain rock itself! There might just be some truth to the legends that warn about an unspeakable evil here…\n\nWe must head into the maze, for our mission cannot be abandoned. If only the overwhelming darkness were all we had to face…",
	LEVEL_38_IRON = "Iron Description 11",
	LEVEL_38_IRON_UNLOCK = "no artillery\nno mage",
	LEVEL_38_MODES_UPGRADES = "lvl 5 max",
	LEVEL_38_TITLE = "The Underpass",
	LEVEL_39_HEROIC = "Heroic Description 12",
	LEVEL_39_HISTORY = "We have been off marching through this stone labyrinth for days without sign of the enemy... until now. Our trackers have found the enemy's trail... but the deeper we go, the hotter it gets!\n\nAncient glyphs on the walls tell us we're heading into the Halls of Beresad, and if the legends are true, we'll get an even warmer reception...",
	LEVEL_39_IRON = "Iron Description 12",
	LEVEL_39_IRON_UNLOCK = "no mages\nno archers",
	LEVEL_39_MODES_UPGRADES = "lvl 5 max",
	LEVEL_39_TITLE = "Beresad's Lair",
	LEVEL_3_HEROIC = "Heroic Description 2",
	LEVEL_3_HISTORY = "While your men celebrate your victory over the goblinoid and orcish troops, a messenger bears bad news.\n\nThe township of Pagras is under siege by an overwhelmingly superior force.\n\nThis is clearly an attack on the Kingdom: war is upon us!",
	LEVEL_3_IRON = "Iron Description 2",
	LEVEL_3_IRON_UNLOCK = "no artillery",
	LEVEL_3_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_3_TITLE = "Pagras",
	LEVEL_40_HEROIC = "Heroic Description 13",
	LEVEL_40_HISTORY = "We've almost run out of supplies, morale is at an all-time low, and some of our men have deserted. Luckily, we've bumped into a Dwarven mining crew that dug too deep and have barricaded themselves against the Saurians.\n\nThey've promised to join us in finding our way out of this damned place. Our escape must wait, as we and our newfound allies must repel the oncoming Saurian horde!",
	LEVEL_40_IRON = "Iron Description 13",
	LEVEL_40_IRON_UNLOCK = "no artillery\nno barracks",
	LEVEL_40_MODES_UPGRADES = "lvl 5 max",
	LEVEL_40_TITLE = "The Dark Descent",
	LEVEL_41_HEROIC = "Heroic Description 14",
	LEVEL_41_HISTORY = "This is it! The final battle against Lord Malagar and his forces is at hand! The dark ritual to unleash his evil master is underway! General, the fate of the world rests upon your shoulders.\n\nWe have travelled through forsaken lands, far beyond the frontiers of our kingdom, in the deadliest of journeys, and only your shining example and exceptional tactics have brought us this far. Only you can see this quest through, and vanquish our enemies. FOR LINIREA!",
	LEVEL_41_IRON = "Iron Description 14",
	LEVEL_41_IRON_UNLOCK = "no mages",
	LEVEL_41_MODES_UPGRADES = "lvl 5 max",
	LEVEL_41_TITLE = "Emberspike Depths",
	LEVEL_42_HEROIC = "Heroic Description 16",
	LEVEL_42_HISTORY = "For the past few weeks, sailors and fishermen have raised the alarm regarding eerie disappearances. Ships and people have been reported missing, vanishing mysteriously in nearby waters. Our Port Tortuga garrison, in the Pirate Islands, is requesting our aid.\n\nWe are still unsure of who or what is behind the disappearances, but our coastal villages are in danger, and our King is asking you to lead a small rapid response fleet to get to the bottom of this new menace.",
	LEVEL_42_IRON = "Iron Description 16",
	LEVEL_42_IRON_UNLOCK = "no mages\nno artillery",
	LEVEL_42_MODES_UPGRADES = "lvl 5 max",
	LEVEL_42_TITLE = "Port Tortuga",
	LEVEL_43_HEROIC = "Heroic Description 16",
	LEVEL_43_HISTORY = "Beware the Deep Devils! We believed these cruel fiends destroyed decades ago by the Linirean Royal Fleet and the Corsair Brotherhood. After the Battle of Port Tortuga, on the verge of being sunk by treacherous tides and the constant attacks of these nasty creatures, we have come ashore in the dangerous Storm Atoll.\n\nHere we prepare for battle, near the ruins of a shrine to Regnos, Lord of the Sea. Pray that Regnos will protect Linirea's defenders!",
	LEVEL_43_IRON = "Iron Description 16",
	LEVEL_43_IRON_UNLOCK = "no archers\nno artillery",
	LEVEL_43_MODES_UPGRADES = "lvl 5 max",
	LEVEL_43_TITLE = "Storm Atoll",
	LEVEL_44_HEROIC = "Heroic Description 18",
	LEVEL_44_HISTORY = "With the Lord of the Sea by our side, we have prevailed in battle! However, the Deep Devils may yet have the last laugh: they have awakened Leviathan, the evil deity of the depths they worship. If Leviathan attains its full power, there is nothing in the world that can stop it.\n\nNo time to regroup or recover, we must head into Leviathan's lair, the city of Ryly'eh, once the seat of Regnos' rule. It is time to defeat the Deep Devils and their malevolent god once and for all!",
	LEVEL_44_IRON = "Iron Description 18",
	LEVEL_44_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_44_MODES_UPGRADES = "lvl 5 max",
	LEVEL_44_TITLE = "The Sunken Citadel",
	LEVEL_45_HEROIC = "Heroic Description 15",
	LEVEL_45_HISTORY = "An endless night is upon us! Something wicked has awakened, plunging the area into darkness! Mindless horrors prowl the land in search of human prey!\n\nOur King has tasked you with protecting the defenseless villagers and finding out what is causing this blight... the realm needs you!",
	LEVEL_45_IRON = "Iron Description 15",
	LEVEL_45_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_45_MODES_UPGRADES = "lvl 5 max",
	LEVEL_45_TITLE = "Bonesburg",
	LEVEL_46_HEROIC = "Heroic Description 15",
	LEVEL_46_HISTORY = "We've freed Bonesburg and chased these nefarious beings to an eerie forest. Can you feel the malice radiating from it? Twisted, gnarled trees house dark altars, stages for forbidden rites. Dark horrors prowl the shadows, battle is upon us!",
	LEVEL_46_IRON = "Iron Description 15",
	LEVEL_46_IRON_UNLOCK = "no artillery\nno mage",
	LEVEL_46_MODES_UPGRADES = "lvl 5 max",
	LEVEL_46_TITLE = "Desecrated Grove",
	LEVEL_47_HEROIC = "Heroic Description 15",
	LEVEL_47_HISTORY = "Deep in the black heart of the forest, we've found the root of this evil. Vasile has risen from his slumber! Vasile once more wields his dark power! Vasile, the ancient vampire prince long thought vanquished! \n\nFrom his mansion, this ancestral foe commands his army of darkness, hoping to turn your troops into a vampiric legion in his thrall. Let us shed light over this darkness, and end this dark night... for Linirea!",
	LEVEL_47_IRON = "Iron Description 15",
	LEVEL_47_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_47_MODES_UPGRADES = "lvl 5 max",
	LEVEL_47_TITLE = "Dusk Chateau",
	LEVEL_48_HEROIC = "Heroic Description 15",
	LEVEL_48_HISTORY = "The Dwarves are one of our staunchest allies, and our King has named them Guardians of the Caves. In their quest for the Lost Kingdom of Loria, they have stumbled upon a network of secret Saurian tunnels. \n\nThrough them, an enormous horde of Saurians is heading for the surface, bent on conquering Linirea under the taloned foot of Xyzzy, the Saurian King. You must join the Dwarves in stopping Xyzzy and his beasts... for only Denas can be King of Linirea!",
	LEVEL_48_IRON = "Iron Description 15",
	LEVEL_48_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_48_MODES_UPGRADES = "lvl 5 max",
	LEVEL_48_TITLE = "Darklight Depths",
	LEVEL_49_HEROIC = "Heroic Description 1",
	LEVEL_49_HISTORY = "General, a band of Gnolls approaches!\nThey are beasts who only think about looting and burning everything in their wake, but they will be sorry they ever left their arid hills...\n\nFor the Queen!",
	LEVEL_49_IRON = "Iron Description 1",
	LEVEL_49_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_49_MODES_UPGRADES = "lvl 1 max",
	LEVEL_49_TITLE = "Gray Ravens",
	LEVEL_4_HEROIC = "Heroic Description 4",
	LEVEL_4_HISTORY = "Enemy troops are marching from the East through the Stonecliff Mountains. This can only mean that Hammerhold has fallen, and our Kingdom's capital is in peril.\n\nOur scouts conclude that the best place to stop our enemy's advance is at the Twin Rivers pass.",
	LEVEL_4_IRON = "Iron Description 4",
	LEVEL_4_IRON_UNLOCK = "no mages\nno artillery",
	LEVEL_4_MODES_UPGRADES = "lvl 2 max\nNo Heroes",
	LEVEL_4_TITLE = "Twin River Pass",
	LEVEL_50_HEROIC = "Heroic Description 2",
	LEVEL_50_HISTORY = "That Gnoll forward patrol was barely a practice fight. Our scouts have spotted a much larger band trying to cross the Old Bridge.\n\nWe shall send them running back to their warrens, their numbers be damned!",
	LEVEL_50_IRON = "Iron Description 2",
	LEVEL_50_IRON_UNLOCK = "no mages\nno druids",
	LEVEL_50_MODES_UPGRADES = "lvl 2 max",
	LEVEL_50_TITLE = "The High Cross",
	LEVEL_51_HEROIC = "Heroic Description 2",
	LEVEL_51_HISTORY = "The massive enemy force crossing downriver has tried to flank us as we expected, General.\n\nWe will be able to ambush the Gnolls and their beasts in the winding paths between the waterfalls.\n\nMay the goddess Elynie bless us!",
	LEVEL_51_IRON = "Iron Description 2",
	LEVEL_51_IRON_UNLOCK = "no archers\nno mages",
	LEVEL_51_MODES_UPGRADES = "lvl 2 max",
	LEVEL_51_TITLE = "Waterfalls Trail",
	LEVEL_52_HEROIC = "Heroic Description 3",
	LEVEL_52_HISTORY = "The Gnoll hills must be empty, because it looks like every single one of those vile creatures has come to invade our lands!\nWe have fought without rest, defeating one band after another, but a larger force aims to destroy the Great Redwood.\n\nThe treefolk are fighting valiantly to defend their home, but they are barely holding... we must rush to their aid!",
	LEVEL_52_IRON = "Iron Description 3",
	LEVEL_52_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_52_MODES_UPGRADES = "lvl 2 max",
	LEVEL_52_TITLE = "Redwood Stand",
	LEVEL_53_HEROIC = "Heroic Description 4",
	LEVEL_53_HISTORY = "Dreadful news, General!\n\nThe capital has fallen! Enemy armies have attacked from every direction, razing everything in their path.\nOnly the Bladesingers fight on, buying time for the Queen's daughter to escape to the gardens.\n\nBy the Light, we must protect Princess Alleria!",
	LEVEL_53_IRON = "Iron Description 4",
	LEVEL_53_IRON_UNLOCK = "no barracks\nno druids",
	LEVEL_53_MODES_UPGRADES = "lvl 3 max",
	LEVEL_53_TITLE = "Royal Gardens",
	LEVEL_54_HEROIC = "Heroic Description 5",
	LEVEL_54_HISTORY = "Malicia, queen of the Twilight Elves is in command of this bloody invasion. She has sent the entire Gnoll horde to kill Alleria, the last of Elynie's lineage. They surround us and we can hear their inhuman howls echo through the Gryphon Peak plateaus.\n\nGeneral, we must resist at all costs, until the young princess can escape safely to Linirea!",
	LEVEL_54_IRON = "Iron Description 5",
	LEVEL_54_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_54_MODES_UPGRADES = "lvl 3 max",
	LEVEL_54_TITLE = "Gryphon Point",
	LEVEL_55_HEROIC = "Heroic Description 5",
	LEVEL_55_HISTORY = "War rages on, we attack and retreat, making the invader pay a steep price for each inch of ground we give up.\n\nAs per your orders, General, we've retreated into the Faery Forest, the archdruids of Rockhenge have always been our allies.\nNevertheless, we can feel hidden, hostile gazes as we make our way through this magical land.",
	LEVEL_55_IRON = "Iron Description 5",
	LEVEL_55_IRON_UNLOCK = "no mages\nno barracks",
	LEVEL_55_MODES_UPGRADES = "lvl 3 max",
	LEVEL_55_TITLE = "Rockhenge",
	LEVEL_56_HEROIC = "Heroic Description 5",
	LEVEL_56_HISTORY = "The fearsome Forest Keepers will fight on our side, but some of the fae have joined our enemies and our troops are nervously wondering what those approaching frumious sounds are...\n\nPraised be Elynie, one of our elite archer groups of Golden Longbows has managed to get through the enemy lines and are holding down a position among the enchanted houses of Grimmsburg. General, they need our help now!",
	LEVEL_56_IRON = "Iron Description 5",
	LEVEL_56_IRON_UNLOCK = "no mages\nno druids",
	LEVEL_56_MODES_UPGRADES = "lvl 3 max",
	LEVEL_56_TITLE = "Grimmsburg",
	LEVEL_57_HEROIC = "Heroic Description 5",
	LEVEL_57_HISTORY = "Our druidic allies feel uneasy about crossing the Crystal Lake, I have heard them whisper about the Grootslang, but they refuse to speak further about the issue. \n\nWe have sent scouts to find the High Elven Mages, who study the magic of the crystals; we hope by the Light to find them in time!\n\nOur enemies are closing in, it's time to double our march and reach the Unseelie Court before our strength wanes.",
	LEVEL_57_IRON = "Iron Description 5",
	LEVEL_57_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_57_MODES_UPGRADES = "lvl 4 max",
	LEVEL_57_TITLE = "The Crystal Lake",
	LEVEL_58_HEROIC = "Heroic Description 5",
	LEVEL_58_HISTORY = "Although we have weathered dozens of onslaughts, we are on the verge of collapse.\nWe press on, towards Neverwonder, which is under the Weirdwoods' protection. If these impressive beings see us as a threat, we will be hopelessly crushed.\n\nThe time has come to risk it all, may Elynie protect us.",
	LEVEL_58_IRON = "Iron Description 5",
	LEVEL_58_IRON_UNLOCK = "no archers\nno barracks",
	LEVEL_58_MODES_UPGRADES = "lvl 4 max",
	LEVEL_58_TITLE = "Neverwonder",
	LEVEL_59_HEROIC = "Heroic Description 5",
	LEVEL_59_HISTORY = "No hope left for the Elves, we will find neither safe haven nor resting place at the Unseelie Court. Our enemies have taken the palace and Malicia has crowned herself Unseelie Queen.\n\nWe are trapped, outnumbered and exhausted... no option left but to fight until our last breath, before we go to Elynie's embrace...\n\nHere they come, General, this will be a battle remembered throughout the ages!",
	LEVEL_59_IRON = "Iron Description 5",
	LEVEL_59_IRON_UNLOCK = "no barracks\nno mages",
	LEVEL_59_MODES_UPGRADES = "lvl 4 max",
	LEVEL_59_TITLE = "The Unseelie Court",
	LEVEL_5_HEROIC = "Heroic Description 5",
	LEVEL_5_HISTORY = "With  Twin Rivers Pass blocked, and after days of marching, we've finally reached the Silveroak Forest outpost... only to find its troop compliment decimated!\n\nThe garrison's men have endured several attacks recently, and their scouts report an even greater enemy force approaching.\n\nGood thing elite ranger units are on the way to help us...",
	LEVEL_5_IRON = "Iron Description 5",
	LEVEL_5_IRON_UNLOCK = "no barracks",
	LEVEL_5_MODES_UPGRADES = "lvl 3 max\nNo Heroes",
	LEVEL_5_TITLE = "Silveroak Forest",
	LEVEL_60_HEROIC = "Heroic Description 5",
	LEVEL_60_HISTORY = "We are still amazed at how deep the evil we face runs. None less than Mactans, one of the Ancient Spider Queens.\n\nGeneral, the scouts you sent followed Malicia's and Mactans' trail. They have fled to the awe-inspiring floating ruins of the First City, where our race originated from and where no Elf has set foot in centuries.\n\nA massive Twilight army awaits us there... no time to catch our breath, the goddess Elynie herself might be in peril!",
	LEVEL_60_IRON = "Iron Description 5",
	LEVEL_60_IRON_UNLOCK = "no mages\nno druids",
	LEVEL_60_MODES_UPGRADES = "lvl 5 max",
	LEVEL_60_TITLE = "The Ascent",
	LEVEL_61_HEROIC = "Heroic Description 5",
	LEVEL_61_HISTORY = "The City and its debris float in the shape of the most dangerous stairway imaginable.\n\nOur enemies retreat into the heart of the City while we doggedly pursue them across deadly chasms. We do not know why they have decided to go around the Arcane Council area. It might be a trap, but it is our only chance to recover some ground.\n\nThere is an ominous silence blanketing the place, as if even the birds fear awakening something...",
	LEVEL_61_IRON = "Iron Description 5",
	LEVEL_61_IRON_UNLOCK = "no archers\nno druids",
	LEVEL_61_MODES_UPGRADES = "lvl 5 max",
	LEVEL_61_TITLE = "Arcane Quarters",
	LEVEL_62_HEROIC = "Heroic Description 5",
	LEVEL_62_HISTORY = "The Twilight Elves are ambushing at every opportunity and the path towards the center of the City has been spattered by dead bodies... ours and theirs.\n\nTaking this pathway of small floortiles levitating over the void was a risky decision, General, but a wise one. The lair of Mactans herself lays ahead.\n\nOur troops are exhausted, but they are committed to end the existence of this abomination tainting our sacred ruins!",
	LEVEL_62_IRON = "Iron Description 5",
	LEVEL_62_IRON_UNLOCK = "no barracks\nno druids",
	LEVEL_62_MODES_UPGRADES = "lvl 5 max",
	LEVEL_62_TITLE = "Mactans' Retreat",
	LEVEL_63_HEROIC = "Heroic Description 5",
	LEVEL_63_HISTORY = "General, enemy armies have been deployed around our goddess' statue. While we speak, Mactans and Malicia unleash their power to take possession of the powerful Tear of Elynie. The place is brimming with the ancient power that gave birth to our race giving our tired soldiers renewed strength.\n\nWe are ready to face this last battle, the fate of our goddess and our race depends on our victory.\n\nFor the Light! For Elynie!",
	LEVEL_63_IRON = "Iron Description 5",
	LEVEL_63_IRON_UNLOCK = "no archers\nno druids",
	LEVEL_63_MODES_UPGRADES = "lvl 5 max",
	LEVEL_63_TITLE = "Shrine of Elynie",
	LEVEL_64_HEROIC = "Heroic Description 5",
	LEVEL_64_HISTORY = "General, we have arrived at the border of Ogres' Fief. Gnoll tribes led by mysterious ogres are overrunning the few troops still defending the ruined wall.\n\nTime is of the essence general, we must rush to their aid!",
	LEVEL_64_IRON = "Iron Description 5",
	LEVEL_64_IRON_UNLOCK = "no archers\nno druids",
	LEVEL_64_MODES_UPGRADES = "lvl 5 max",
	LEVEL_64_TITLE = "Galadrian's Wall",
	LEVEL_65_HEROIC = "Heroic Description 5",
	LEVEL_65_HISTORY = "This is where the Ogres extract the corrupted mineral that feeds their sorcery. We can weaken their warlocks if we manage to cut off their supply of bloodsydian.\n\nGeneral, we must also fight to free all the slaves!",
	LEVEL_65_IRON = "Iron Description 16",
	LEVEL_65_IRON_UNLOCK = "no mages\nno archers",
	LEVEL_65_MODES_UPGRADES = "lvl 5 max",
	LEVEL_65_TITLE = "Blood Quarry",
	LEVEL_66_HEROIC = "Heroic Description 5",
	LEVEL_66_HISTORY = "The ogres and their gnoll allies have retreated to the village of their cruel king, Bram the Beheader. This will be a terrible fight with no quarter, General.\n\nThis is our chance to end the ogre menace to our lands once and for all.\n\nFor the Kingdom!",
	LEVEL_66_IRON = "Iron Description 5",
	LEVEL_66_IRON_UNLOCK = "no mages\nno druids",
	LEVEL_66_MODES_UPGRADES = "lvl 5 max",
	LEVEL_66_TITLE = "Beheader's Seat",
	LEVEL_67_HEROIC = "Heroic Description 5",
	LEVEL_67_HISTORY = "General, we must advance without delay to the Twilight Elves' capital. Malicia's last loyal lieutenant is preparing a terrible and powerful spell that will destroy everything in sight.\n\nIf we don't stop him this will be the end of the continent!",
	LEVEL_67_IRON = "Iron Description 5",
	LEVEL_67_IRON_UNLOCK = "no mages\nno archers",
	LEVEL_67_MODES_UPGRADES = "lvl 5 max",
	LEVEL_67_TITLE = "Duskwood Outpost",
	LEVEL_68_HEROIC = "Heroic Description 15",
	LEVEL_68_HISTORY = "This is the final push, General!\n\nWe have routed enough enemy troops to march upon the city gates. Baj'Nimen has no other choice but to come out and fight.\n\nThis will be our chance to stop his plans before it's too late.",
	LEVEL_68_IRON = "Iron Description 15",
	LEVEL_68_IRON_UNLOCK = "no barracks\nno druids",
	LEVEL_68_MODES_UPGRADES = "lvl 5 max",
	LEVEL_68_TITLE = "Duredhel Outskirts",
	LEVEL_69_HEROIC = "Heroic Description 15",
	LEVEL_69_HISTORY = "War is over or so we thought...\n\nBecause even as our Kingdom goes back to its former peace and prosperity, the messengers we sent asking for aid from the Dwarves never returned. And if there's something more troublesome than a loud dwarf, it's a silent one.\n\nYou must travel to their land and seek answers.",
	LEVEL_69_IRON = "Iron Description 15",
	LEVEL_69_IRON_UNLOCK = "no mages\nno druids",
	LEVEL_69_MODES_UPGRADES = "lvl 5 max",
	LEVEL_69_TITLE = "Dwaraman Gates",
	LEVEL_6_HEROIC = "Heroic Description 6",
	LEVEL_6_HISTORY = "After several days of travel, we have arrived at our capital city of Linirea.\nThe time has come to make a stand, and defend Linirea's southern walls. \n\nIn addition to your highly experienced units, the King adds two units to your batallions. The arcane wizards will provide superior firepower, and the pious paladins will inspire the troops with their bravery.",
	LEVEL_6_IRON = "Iron Description 6",
	LEVEL_6_IRON_UNLOCK = "only barracks",
	LEVEL_6_MODES_UPGRADES = "lvl 3 max\nNo Heroes",
	LEVEL_6_TITLE = "The Citadel",
	LEVEL_70_HEROIC = "Heroic Description 5",
	LEVEL_70_HISTORY = "General!\n\nThe once proud and powerful dwarves have been exterminated by a powerful demon released by mistake.\n\nWe must avenge our former allies and defeat Godieth the Infernal before he reaches the surface and unleashes a reign of terror.",
	LEVEL_70_IRON = "Iron Description 15",
	LEVEL_70_IRON_UNLOCK = "no archers\nno druids",
	LEVEL_70_MODES_UPGRADES = "lvl 5 max",
	LEVEL_70_TITLE = "Tainted Pit",
	LEVEL_7_HEROIC = "Heroic Description 7",
	LEVEL_7_HISTORY = "Our capital is safe, thanks to you, General! Now, our good King has entrusted you with the mission of creating a safe passage through the mountains so that we may strike at Valardul, and defeat Vez'nan and his armies.\n\nThe first step in your journey will be the Coldstep Mines, which were abandoned years ago, and are now home to the Ha'kraj troll tribes. To aid you in your mission, you will be joined by a brigade of His Majesty's Royal Musketeers.",
	LEVEL_7_IRON = "Iron Description 7",
	LEVEL_7_IRON_UNLOCK = "no barracks\nno artillery",
	LEVEL_7_MODES_UPGRADES = "lvl 3 max\nNo Heroes",
	LEVEL_7_TITLE = "Coldstep Mines",
	LEVEL_8_HEROIC = "Heroic Description 8",
	LEVEL_8_HISTORY = "There is no place colder in these mountains than Icewind Pass, but we must advance.\n\nOur men have been besieged by Ha'kraj trolls for days, and our scouts report enemy troop movements around us... and something else, something wilder.\n\nIf we are to make a stand here, this is a good place to install some of our new Artillery emplacements, and to construct a Barbarian Mead Hall so we may entertain our more... colorful troops.",
	LEVEL_8_IRON = "Iron Description 8",
	LEVEL_8_IRON_UNLOCK = "no archer\nno mage",
	LEVEL_8_MODES_UPGRADES = "lvl 4 max\nNo Heroes",
	LEVEL_8_TITLE = "Icewind Pass",
	LEVEL_9_HEROIC = "Heroic Description 9",
	LEVEL_9_HISTORY = "Arriving at the Stormcloud temple has been the best thing to happen to us in days!\n\nThe Stormcloud Sorcerers will now be at your command, General, and they can open a portal straight to Valardul. However, we must provide them with a defense while they complete their spell.\n\nSomething... abominable is aproaching, and the men are extremely nervous...",
	LEVEL_9_IRON = "Iron Description 9",
	LEVEL_9_IRON_UNLOCK = "only mages",
	LEVEL_9_MODES_UPGRADES = "lvl 4 max\nNo Heroes",
	LEVEL_9_TITLE = "Stormcloud Temple",
