	TERMS_OF_SERVICE_LINK = "Terms of Service",
	["TIP!"] = "TIP!",
	TIP_1 = "Don't bring all your vanilla habits here - try some new strategies!",
	TIP_10 = "Big Bertha's dragon-breath missiles split apart, and their trajectory is beautiful!",
	TIP_11 = "Max out the original Arcane Wizard's instakill... and you can instakill skeletons forever!",
	TIP_12 = "The Musketeer tower's sniper range is twice its basic attack range. A hundred paces, one shot!",
	TIP_13 = "Gunshot damage is a damage type with slightly less armor piercing than artillery damage.",
	TIP_14 = "Use Sir Gerald to protect your barbarian soldiers!",
	TIP_15 = "Upgrade a barracks to train new soldiers immediately.",
	TIP_16 = "Calling a wave early earns bonus gold and slightly reduces spell cooldowns.",
	TIP_17 = "Artillery cannot target flying enemies directly, but its explosions can still damage them.",
	TIP_18 = "Use barracks or reinforcements to isolate troublesome enemies.",
	TIP_19 = "When clearing wolves, elven rangers are more efficient in melee than at range.",
	TIP_2 = "Support your barracks with ranged attacks to keep enemies exposed for as long as possible.",
	TIP_20 = "Rally your reinforcements according to the flow of the battle.",
	TIP_21 = "Hover over the next wave icon to check which enemies are coming.",
	TIP_22 = "Never underestimate silence: it stops most enemies from attacking at range, using skills, or even triggering deathrattles!",
	TIP_23 = "Stuck? Try changing your towers and heroes - you may be surprised!",
	TIP_24 = "Dante can help slow-leveling heroes gain levels quickly!",
	TIP_25 = "Playing Setham well lets you control when Divine Wrath fires!",
	TIP_26 = "The Wild Magus's attack starts out at its very best!",
	TIP_27 = "The High Elven Mage earned a doctorate at the College of Support Magic.",
	TIP_28 = "Enemies too densely packed? Try the Arch-Druid!",
	TIP_29 = "The Golden Longbows have absolute dominance over high-health units.",
	TIP_3 = "We have four upgrade lines, but only one can be active at a time! Pick the right one for the stage!",
	TIP_30 = "Jungle Amazons are exceptionally effective in the Fungal Forest.",
	TIP_31 = "Tesla, Earthquake, Rotten Forest, Flamespitter and the Goblin Ballista benefit extra from range bonuses.",
	TIP_32 = "Polymorph instakills ignore Impossible difficulty's instakill resistance!",
	TIP_33 = "The Ghost Warrior is an excellent Sunray tower launcher.",
	TIP_34 = "The Ghost Warrior can stack dragon souls together.",
	TIP_35 = "A shield-spec Paladin from the fifth game cannot be bitten to death by Cloud Eagles.",
	TIP_36 = "Attacks from the fifth game's undead tower can seal some enemies' deathrattles.",
	TIP_37 = "Lacking a focus-fire spot? Try upgrade line 3!",
	TIP_38 = "Upgrade line 1 has the cheapest artillery.",
	TIP_39 = "Two Royal Archers can acquire targets independently!",
	TIP_4 = "Archer towers prioritize air units.",
	TIP_40 = "When you have tower spots to spare, level 1 barracks are great value.",
	TIP_41 = "Plugins require both the plugin manager and the plugin itself to be enabled, plus a game restart, before they take effect!",
	TIP_42 = "The base game's author is not responsible for the balance or stability of other plugins!",
	TIP_43 = "If an update is too large, try re-downloading the base game - be kind to the potato server QAQ",
	TIP_44 = "Some plugin changes need a restart; the plugin manager's Apply button will take care of it.",
	TIP_45 = "For Shaolin monks locked onto the same target, the damage of the third and later monks is reduced.",
	TIP_46 = "When a plugin reports an error, first try updating it to the latest version.",
	TIP_47 = "When enemies in range are blocked, the Red Diamond attacks the most recently blocked unit.",
	TIP_48 = "Harassers can still shoot in melee.",
	TIP_49 = "With the power of the Holy Grail, defeating facehuggers is a given.",
	TIP_5 = "If some towers' targeting looks strange, maybe some enemies are taunting them?",
	TIP_50 = "Goblin rocket fragments get stopped by crowds - and then deal heavy damage!",
	TIP_51 = "Ha! Ha! Ha!",
	TIP_52 = "Due to limited time, Endless mode is currently unmaintained. Thank you for understanding.",
	TIP_6 = "Dwarven musketeers pack a punch. A really big punch.",
	TIP_7 = "The Holy Grail is the bane of status effects.",
	TIP_8 = "Disintegration prevents some enemies' deathrattles from triggering.",
	TIP_9 = "The Archmage's orb picks a suitable target automatically. Magic time!",
